import { createFileRoute } from "@tanstack/react-router";
import { DevicesBody } from "@/components/devices/devices-body";

/**
 * Device pairing only.
 *
 * Sandboxes used to share this page under a "Runtime" tab. They are now
 * synthesized into the connectors list (runtime facet), the same way model
 * providers are. Device-bound connectors already appear under Connectors with
 * the "On device" filter — this page is just the install/pair surface for the
 * Mac app, Chrome extension, and CLI (linked from the user menu as
 * "My devices").
 *
 * `?provider=` is accepted for back-compat with old sandbox deep links and is
 * ignored here; those links now resolve via the connectors list after redirect
 * from /environments.
 */
export const Route = createFileRoute("/$owner/connectors/runtime/")({
	component: DevicesPage,
});

function DevicesPage() {
	const { owner } = Route.useParams();

	return (
		<div className="mx-auto flex w-full max-w-3xl flex-1 flex-col gap-6">
			<div className="space-y-0.5">
				<h1 className="text-sm font-semibold">My devices</h1>
				<p className="text-xs text-muted-foreground">
					Pair a Mac, browser extension, or CLI to run device-bound connectors.
					Those connectors appear under Connect with the On device filter.
				</p>
			</div>
			<DevicesBody owner={owner} />
		</div>
	);
}

