import { createFileRoute, redirect } from "@tanstack/react-router";

// Sandboxes live under Connectors now (runtime facet + sandbox-provider kinds).
// Old /environments links still resolve.
export const Route = createFileRoute("/$owner/environments/")({
	beforeLoad: ({ params }) => {
		throw redirect({
			to: "/$owner/connectors",
			params: { owner: params.owner },
			search: { entity_id: undefined },
		});
	},
});

/**
 * Resolve the config-prefill target to a provider kind we should actually act on.
 * Only honor `targetProvider` when it's one the org can add (`availableProviders`
 * includes it): a bogus `?provider=…` must not show a banner for a nonexistent
 * provider or open a form it can't fill, and an empty list (still loading) holds
 * the prefill until the providers arrive. Returns undefined otherwise.
 *
 * Kept for deep-link helpers that still validate ?provider= before routing to
 * `/connectors/sandbox-provider:{kind}`.
 */
export function resolvePrefillProvider(
	targetProvider: string | undefined,
	availableProviders: string[],
): string | undefined {
	return targetProvider && availableProviders.includes(targetProvider)
		? targetProvider
		: undefined;
}

