describe("provider detail route resolution", () => {
	afterEach(() => {
		// The inference hooks scope off window.location (getPathScope), which the
		// memory-history router does not drive — reset the jsdom URL between tests.
		window.history.replaceState(null, "", "/");
	});

	it("a connected provider's prefixed key renders the management body", async () => {
		window.history.replaceState(null, "", PATH);
		const { findByText, findByRole, queryByText, unmount } = await renderRoute(
			PATH,
			{ authenticated: true, extraHandlers: handlers([PROVIDER]) },
		);

		// Management-only affordances prove the provider branch resolved…
		await findByRole("button", { name: "Set as default" });
		await findByText("Cerebras");
		// …and the connector-catalog fallback did NOT.
		expect(queryByText(/isn't installed in this workspace/)).toBeNull();
		unmount();
	});

	it("an unconnected catalog kind renders the create-provider form", async () => {
		window.history.replaceState(null, "", PATH);
		const { findByText, queryByText, unmount } = await renderRoute(PATH, {
			authenticated: true,
			extraHandlers: handlers([]),
		});

		// Kind is locked from the catalog card — no second Provider picker.
		await findByText(/Connect /);
		expect(queryByText(/isn't installed in this workspace/)).toBeNull();
		unmount();
	});
});

