import { HttpResponse, http } from "msw";
import { afterEach, describe, expect, it } from "vitest";
import { renderRoute } from "@/test/render";

/**
 * Detail-route resolution for prefixed provider keys: /$owner/connectors/
 * inference-provider%3A<slug> must resolve as a PROVIDER (management body when
 * the org has it, the create form when only the catalog knows the kind) — not
 * fall through to the connector-catalog path and its "isn't installed" dead
 * end. The percent-encoded path is deliberate: it is exactly what the server's
 * URL builders emit into chat messages, so this also proves the router decodes
 * `%3A` back into the prefix.
 */

const ok = (body: unknown) =>
	HttpResponse.json(body as Record<string, unknown>);

const WORKSPACE = {
	workspace: {
		slug: "test-org",
		type: "organization",
		id: "org-1",
		name: "Test Org",
	},
	segments: [],
	path: [],
	entity: null,
	children: [],
	siblings: [],
	bootstrap: null,
};

const PROVIDER = {
	id: 1,
	slug: "cerebras",
	kind: "cerebras",
	displayName: "Cerebras",
	capabilities: {
		text: { base_url: "https://api.cerebras.ai/v1", model: "llama-3.3-70b" },
	},
	hasCustomUpstream: false,
	isDefault: false,
	status: "active",
	createdAt: null,
};

const CATALOG_ITEM = {
	slug: "cerebras",
	displayName: "Cerebras",
	iconUrl: "",
	authType: "api-key",
	supportedAuthTypes: ["api-key"],
	sdkCompat: "openai",
	baseUrl: "https://api.cerebras.ai/v1",
	defaultModel: "llama-3.3-70b",
	modelsEndpoint: "/v1/models",
	systemAvailable: false,
	models: [],
	apiKeyPlaceholder: "",
	apiKeyInstructions: "",
	modalities: ["text"],
};

const PATH = "/test-org/connectors/inference-provider%3Acerebras";

function handlers(providers: unknown[]) {
	return [
		http.post("*/api/:slug/resolve_path", () => ok(WORKSPACE)),
		http.get("*/api/:slug/agents/inference-providers", () => ok({ providers })),
		http.get("*/api/:slug/agents/inference-providers/catalog", () =>
			ok({ catalog: [CATALOG_ITEM] }),
		),
	];
}

describe("provider detail route resolution", () => {
	afterEach(() => {
		// The inference hooks scope off window.location (getPathScope), which the
		// memory-history router does not drive — reset the jsdom URL between tests.
		window.history.replaceState(null, "", "/");
	});

	it("a connected provider's prefixed key renders the management body", async () => {
		window.history.replaceState(null, "", PATH);
		const { findByText, findByRole, queryByText, unmount } = await renderRoute(
			PATH,
			{ authenticated: true, extraHandlers: handlers([PROVIDER]) },
		);

		// Management-only affordances prove the provider branch resolved…
		await findByRole("button", { name: "Set as default" });
		await findByText("Cerebras");
		// …and the connector-catalog fallback did NOT.
		expect(queryByText(/isn't installed in this workspace/)).toBeNull();
		unmount();
	});

	it("an unconnected catalog kind renders the create-provider form", async () => {
		window.history.replaceState(null, "", PATH);
		const { findByText, queryByText, unmount } = await renderRoute(PATH, {
			authenticated: true,
			extraHandlers: handlers([]),
		});

		// Kind is locked from the catalog card — no second Provider picker.
		await findByText(/Connect /);
		expect(queryByText(/isn't installed in this workspace/)).toBeNull();
		unmount();
	});
});

