			<div className="mx-auto w-full max-w-3xl space-y-4">
				<div className="flex items-center gap-2">
					<Skeleton className="h-6 w-6 rounded" />
					<Skeleton className="h-5 w-40" />
				</div>
				<Skeleton className="h-24 w-full rounded-lg" />
			</div>
		);
	}

	if (!sandbox) {
		return (
			<div className="mx-auto w-full max-w-3xl space-y-3">
				<p className="text-sm text-muted-foreground">
					This sandbox isn't in this workspace, so its details aren't available.
				</p>
				<Button
					variant="outline"
					size="sm"
					onClick={() =>
						void navigate({
							to: "/$owner/connectors",
							params: { owner: ownerSlug },
						})
					}
				>
					Back to connectors
				</Button>
			</div>
		);
	}

	return (
		<div className="mx-auto w-full max-w-3xl space-y-6">
			<DetailHeader
				breadcrumb={
					<DetailBreadcrumb
						crumbs={[
							<Link
								key="connectors"
								to="/$owner/connectors"
								params={{ owner: ownerSlug }}
								className={DETAIL_CRUMB_LINK_CLASS}
							>
								Connectors
							</Link>,
						]}
					/>
				}
				icon={
					<span className="flex h-8 w-8 items-center justify-center rounded-md bg-muted text-muted-foreground">
						<Plug className="h-4 w-4" />
					</span>
				}
				title={sandbox.name || sandbox.providerKind}
				badge={
					<>
						<Badge variant="secondary">{sandbox.providerKind}</Badge>
						{sandbox.connected ? (
							<Badge className="border-transparent bg-emerald-500/10 text-emerald-500">
								Connected
							</Badge>
						) : (
							<Badge variant="destructive">No credential</Badge>
						)}
					</>
				}
				status={<FacetChips facets={RUNTIME_ONLY_FACETS} />}
			/>
			<SandboxDetail
				sandbox={sandbox}
				onDeleted={() =>
					void navigate({
						to: "/$owner/connectors",
						params: { owner: ownerSlug },
					})
				}
			/>
		</div>
	);
}

