toolUseResult.originalFile:
import { AlertTriangle, Box, Server, Trash2 } from "lucide-react";
import { useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Spinner } from "@/components/ui/spinner";
import {
	type SandboxItem,
	useDeleteSandbox,
} from "@/lib/api/sandboxes";

/**
 * Flat sandbox detail body for the shared connector detail page.
 *
 * A sandbox is a credential + a short status — one subject, no tabs. Delete
 * lives here (not a Settings tab) because there is nothing else to configure
 * on the row once the vault credential is set at create time.
 */
export function SandboxDetail({
	sandbox,
	onDeleted,
}: {
	sandbox: SandboxItem;
	onDeleted: () => void;
}) {
	const deleteSandbox = useDeleteSandbox();
	const [confirmingDelete, setConfirmingDelete] = useState(false);
	const details = Object.entries(sandbox.details ?? {});

	return (
		<div className="space-y-6">
			<div className="rounded-lg border p-4 space-y-3">
				<div className="flex flex-wrap items-center gap-2">
					<ProviderGlyph kind={sandbox.providerKind} />
					<span className="text-sm font-medium">{sandbox.name}</span>
					<Badge
						variant="secondary"
						className="h-4 px-1.5 py-0 text-[10px] uppercase tracking-wide"
					>
						{sandbox.providerKind}
					</Badge>
					{sandbox.connected ? (
						<Badge className="h-4 border-transparent bg-emerald-500/10 px-1.5 py-0 text-[10px] uppercase tracking-wide text-emerald-500">
							Connected
						</Badge>
					) : (
						<Badge
							variant="destructive"
							className="h-4 border-transparent bg-destructive/10 px-1.5 py-0 text-[10px] uppercase tracking-wide text-destructive"
						>
							No credential
						</Badge>
					)}
				</div>
				{details.length > 0 ? (
					<p className="font-mono text-[11px] text-muted-foreground">
						{details.map(([k, v]) => `${k}: ${v}`).join("  |  ")}
					</p>
				) : (
					<p className="text-sm text-muted-foreground">
						Remote sandbox agents execute in instead of the built-in local
						runtime.
					</p>
				)}
				{!sandbox.connected ? (
					<div className="flex gap-2 rounded-md border border-amber-200 bg-amber-50 p-3 text-sm text-amber-950 dark:border-amber-900/60 dark:bg-amber-950/30 dark:text-amber-100">
						<AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" />
						<p>
							This sandbox has no vault credential. Delete it and re-add the
							provider with a valid key, or set the credential via the API.
						</p>
					</div>
