/**
 * Credential form for a picked sandbox provider kind, rendered inside the
 * "Add a connection" page.
 *
 * A sandbox is not a `connection` row, so it cannot go through
 * `form.selectedConnector` — but from the user's side it is the same act
 * (pick a thing from the catalog, give it a credential), so it gets the same
 * Back + chip header and the same page chrome rather than its own surface.
 */
function SandboxKindCreatePanel({
  providerKind,
  ownerSlug,
  onBack,
}: {
  providerKind: string;
  ownerSlug: string;
  onBack: () => void;
}) {
  const navigate = useNavigate();
  const createSandbox = useCreateSandbox();
  const label = sandboxProviderLabel(providerKind);

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-2">
        <Button
          variant="ghost"
          size="sm"
          onClick={onBack}
          className="h-7 px-2 text-xs"
        >
          &larr; Back
        </Button>
        <ConnectorDisplay
          connector={{
            key: `${SANDBOX_PROVIDER_KEY_PREFIX}${providerKind}`,
            name: label,
          }}
          showDescription={false}
          className="gap-2"
        />
        <FacetChips facets={sandboxCatalogFacets()} />
      </div>
      <CreateSandboxForm
        providerKind={providerKind}
        pending={createSandbox.isPending}
        onCancel={onBack}
        onCreate={(payload) =>
          createSandbox.mutate(payload, {
            onSuccess: (result) => {
              const id = result?.sandbox?.id;
              void navigate({
                to: id
                  ? "/$owner/connectors/$connectorKey"
                  : "/$owner/connectors",
                params: id
                  ? { owner: ownerSlug, connectorKey: `sandbox:${id}` }
                  : { owner: ownerSlug },
              });
            },
          })
        }
      />
    </div>
  );
}
