22	type VercelCredentials = {
23	  token: string;
24	  teamId: string;
25	  projectId: string;
26	};
27	
28	function parsePositiveInt(value: string | undefined, fallback: number): number {
29	  if (!value) return fallback;
30	  const parsed = Number.parseInt(value, 10);
31	  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
32	}
33	
34	function parseNonNegativeInt(value: string | undefined): number | undefined {
35	  if (!value) return undefined;
36	  const parsed = Number.parseInt(value, 10);
37	  return Number.isFinite(parsed) && parsed >= 0 ? parsed : undefined;
38	}
39	
40	function parseBoolean(value: string | undefined, fallback: boolean): boolean {
41	  if (!value) return fallback;
42	  const normalized = value.trim().toLowerCase();
43	  if (["1", "true", "yes", "on"].includes(normalized)) return true;
44	  if (["0", "false", "no", "off"].includes(normalized)) return false;
45	  return fallback;
46	}
47	
48	function snapshotRetention(): SnapshotRetention {
49	  const snapshotExpiration = parseNonNegativeInt(
50	    process.env.LOBU_VERCEL_SANDBOX_SNAPSHOT_EXPIRATION_MS
51	  );
52	  const keepCount = Math.min(
53	    10,
54	    Math.max(
55	      1,
56	      parsePositiveInt(process.env.LOBU_VERCEL_SANDBOX_KEEP_LAST_SNAPSHOTS, 1)
57	    )
58	  );
59	  return {
60	    ...(snapshotExpiration !== undefined ? { snapshotExpiration } : {}),
61	    keepLastSnapshots: {
62	      count: keepCount,
63	      ...(snapshotExpiration !== undefined
64	        ? { expiration: snapshotExpiration }
65	        : {}),
66	      deleteEvicted: parseBoolean(
67	        process.env.LOBU_VERCEL_SANDBOX_DELETE_EVICTED_SNAPSHOTS,
68	        true
69	      ),
70	    },
71	  };
72	}
73	
74	/**
75	 * The credential resolver hands us token/teamId/projectId together (all
76	 * `required`), but stay defensive: an empty `values` map means "fall back to
77	 * the Vercel SDK's ambient/OIDC auth" exactly as the original route did.
78	 */
79	function vercelCredentials(
80	  values: Record<string, string>
81	): Partial<VercelCredentials> {
82	  const { token, teamId, projectId } = values;
83	  const present = [token, teamId, projectId].filter((value) => !!value).length;
84	  if (present === 0) return {};
85	  if (present !== 3 || !token || !teamId || !projectId) {
86	    throw new Error(
87	      "VERCEL_TOKEN, VERCEL_TEAM_ID, and VERCEL_PROJECT_ID must be set together"
88	    );
89	  }
90	  return { token, teamId, projectId };
91	}
