93	function stableSandboxName(params: {
94	  organizationId?: string;
95	  agentId: string;
96	  conversationId: string;
97	}): string {
98	  const prefix = (process.env.LOBU_VERCEL_SANDBOX_NAME_PREFIX || "lobu")
99	    .toLowerCase()
100	    .replace(/[^a-z0-9-]/g, "-")
101	    .replace(/^-+|-+$/g, "")
102	    .slice(0, 32);
103	  const org = (params.organizationId || "orgless")
104	    .toLowerCase()
105	    .replace(/[^a-z0-9-]/g, "-")
106	    .replace(/^-+|-+$/g, "")
107	    .slice(0, 24);
108	  const agent = params.agentId
109	    .toLowerCase()
110	    .replace(/[^a-z0-9-]/g, "-")
111	    .replace(/^-+|-+$/g, "")
112	    .slice(0, 24);
113	  const hash = createHash("sha256")
114	    .update(
115	      `${params.organizationId || ""}:${params.agentId}:${params.conversationId}`
116	    )
117	    .digest("hex")
118	    .slice(0, 16);
119	  return [prefix || "lobu", org || "orgless", agent || "agent", hash]
120	    .join("-")
121	    .slice(0, 100);
122	}
123	
124	function sameSnapshotRetention(
125	  actual: Sandbox["keepLastSnapshots"],
126	  expected: SnapshotRetention["keepLastSnapshots"],
127	  actualExpiration: Sandbox["snapshotExpiration"],
128	  expectedExpiration: SnapshotRetention["snapshotExpiration"]
129	): boolean {
130	  return (
131	    actual?.count === expected?.count &&
132	    actual?.expiration === expected?.expiration &&
133	    actual?.deleteEvicted === expected?.deleteEvicted &&
134	    actualExpiration === expectedExpiration
135	  );
136	}
137	
138	function normalizeAllowedDomain(domain: string): string | null {
139	  const trimmed = domain.trim();
140	  if (!trimmed) return null;
141	  if (trimmed === "*") return "*";
142	  if (!/^[A-Za-z0-9.*_-]+(?::\d+)?$/.test(trimmed)) return null;
143	  // Canonicalize (lowercase + punycode, "*.x" collapses to ".x") so
144	  // allow/deny overlap checks compare the one form DNS actually resolves —
145	  // a mixed-case deny must still subtract its allow entry.
146	  const canonical = normalizeDomainPattern(trimmed);
147	  if (canonical.startsWith(".")) return `*${canonical}`;
148	  return canonical;
149	}
150	
151	/**
152	 * True when `entry` (a normalized allow pattern, possibly `*.suffix`) overlaps
153	 * `denied` (same forms) in either direction. The sandbox network policy can
154	 * only express an allow list, so any allow entry a deny covers — or that
155	 * covers a deny — must be dropped rather than granted (fail closed).
156	 */
157	function overlapsDeny(entry: string, denied: string[]): boolean {
158	  // Compare bare hostnames: strip the wildcard prefix AND any :port
159	  // qualifier, so "evil.example.com:443" cannot dodge a deny on
160	  // "evil.example.com".
161	  const bare = (p: string) =>
162	    (p.startsWith("*.") ? p.slice(2) : p).replace(/:\d+$/, "");
163	  const isWild = (p: string) => p.startsWith("*.");
164	  const covers = (pattern: string, host: string) =>
165	    isWild(pattern)
166	      ? host === bare(pattern) || host.endsWith(`.${bare(pattern)}`)
167	      : host === pattern;
168	  return denied.some(
169	    (deny) =>
170	      covers(deny, bare(entry)) ||
171	      covers(entry, bare(deny)) ||
172	      bare(deny) === bare(entry)
173	  );
174	}
175	
176	function networkPolicyFromDomains(
177	  value: unknown,
178	  deniedValue?: unknown
179	): NetworkPolicy {
180	  if (!Array.isArray(value)) return "deny-all";
181	  const normalize = (input: unknown) =>
182	    (Array.isArray(input) ? input : [])
183	      .filter((entry): entry is string => typeof entry === "string")
184	      .map(normalizeAllowedDomain)
185	      .filter((entry): entry is string => !!entry);
186	  const domains = normalize(value);
187	  const denied = normalize(deniedValue);
188	  if (domains.includes("*") && denied.length === 0) return "allow-all";
189	  // The provider policy has no deny primitive, so denies are enforced by
190	  // subtraction: drop "*" (an unbounded allow can't honor exclusions) and
191	  // any allow entry that overlaps a denied pattern.
192	  const allowed = domains.filter(
193	    (entry) => entry !== "*" && !overlapsDeny(entry, denied)
194	  );
195	  return allowed.length > 0
196	    ? { allow: Array.from(new Set(allowed)) }
197	    : "deny-all";
198	}
199	
200	async function getSandbox(params: {
201	  name: string;
202	  networkPolicy: NetworkPolicy;
203	  credentials: Record<string, string>;
204	}): Promise<Sandbox> {
205	  const timeout = parsePositiveInt(
206	    process.env.LOBU_VERCEL_SANDBOX_TIMEOUT_MS,
207	    parsePositiveInt(process.env.TIMEOUT_MINUTES, 10) * 60 * 1000
208	  );
209	  const vcpus = parsePositiveInt(process.env.LOBU_VERCEL_SANDBOX_VCPUS, 1);
210	  const runtime =
211	    process.env.LOBU_VERCEL_SANDBOX_RUNTIME ||
212	    process.env.VERCEL_SANDBOX_DEFAULT_RUNTIME ||
213	    "node24";
214	  const retention = snapshotRetention();
215	  const sandbox = await Sandbox.getOrCreate({
216	    name: params.name,
217	    ...vercelCredentials(params.credentials),
218	    persistent: true,
219	    runtime,
220	    timeout,
221	    resources: { vcpus },
222	    networkPolicy: params.networkPolicy,
223	    ...retention,
224	    tags: { app: "lobu", backend: "worker" },
225	  });
226	
227	  if (
228	    JSON.stringify(sandbox.networkPolicy) !==
229	      JSON.stringify(params.networkPolicy) ||
230	    sandbox.timeout !== timeout ||
231	    sandbox.vcpus !== vcpus ||
232	    !sameSnapshotRetention(
233	      sandbox.keepLastSnapshots,
234	      retention.keepLastSnapshots,
235	      sandbox.snapshotExpiration,
236	      retention.snapshotExpiration
237	    )
238	  ) {
239	    await sandbox.update({
240	      networkPolicy: params.networkPolicy,
241	      resources: { vcpus },
242	      timeout,
243	      ...retention,
244	    });
245	  }
246	  return sandbox;
247	}
248	
249	/**
250	 * Vercel persistent-sandbox runtime (gateway side). The sandbox name is
251	 * deterministic per (org, agent, conversation) so messages resume the same
252	 * filesystem; the filesystem is the persistent source of truth (no file sync).
253	 */
254	export const __testOnly = { networkPolicyFromDomains };
255	
256	export const vercelGatewayRuntimeProvider: GatewayRuntimeProvider = {
257	  id: "vercel",
258	  credentialFields: [
259	    {
260	      key: "token",
261	      systemEnvVar: "VERCEL_TOKEN",
262	      required: true,
263	      secret: true,
264	      label: "Access token",
265	    },
266	    {
267	      key: "teamId",
268	      systemEnvVar: "VERCEL_TEAM_ID",
269	      required: true,
270	      secret: false,
271	      label: "Team ID",
272	    },
273	    {
274	      key: "projectId",
275	      systemEnvVar: "VERCEL_PROJECT_ID",
276	      required: true,
277	      secret: false,
278	      label: "Project ID",
279	    },
280	  ],
281	  canSelfAuth(): boolean {
282	    // Vercel's recommended auth: an ambient OIDC token (present when Lobu runs
283	    // on Vercel, or pulled via `vercel env pull`). The SDK self-resolves it.
284	    return !!process.env.VERCEL_OIDC_TOKEN?.trim();
285	  },
286	  async exec(ctx: RuntimeExecContext): Promise<RuntimeExecResult> {
287	    const sandboxName = stableSandboxName({
288	      organizationId: ctx.organizationId,
289	      agentId: ctx.agentId,
290	      conversationId: ctx.conversationId,
291	    });
292	    const networkPolicy = networkPolicyFromDomains(
293	      ctx.allowedDomains,
294	      ctx.deniedDomains
295	    );
296	    const sandbox = await getSandbox({
