300	    });
301	
302	    await sandbox.fs.mkdir(REMOTE_WORKSPACE_DIR, { recursive: true });
303	
304	    const result = await sandbox.runCommand({
305	      cmd: "/bin/bash",
306	      args: ["-lc", ctx.command],
307	      cwd: remoteCwd(ctx.cwd, ctx.workspaceDir, REMOTE_WORKSPACE_DIR),
308	      env: ctx.env,
309	      timeoutMs: ctx.timeoutMs,
310	    });
311	    const [stdout, stderr] = await Promise.all([
312	      result.stdout(),
313	      result.stderr(),
314	    ]);
315	
316	    return {
317	      stdout,
318	      stderr,
319	      exitCode: result.exitCode,
320	      meta: {
321	        name: sandbox.name,
322	        persistent: sandbox.persistent,
