import { useMemo } from "react";
import { useOrgContext } from "@/hooks/use-org-context";
import { useEntityTypes } from "@/lib/api/entities";
import { isSystemEntityType } from "@/lib/reserved";

/**
 * The workspace's user-visible entity types: drop system/reserved types and any
 * type owned by a different org. Shared by the entity-type rail and the memory
 * scope-bar Type dropdown so both show exactly the same list.
 */
export function useVisibleEntityTypes(ownerSlug: string) {
	const { orgContext } = useOrgContext();
	const { data: entityTypes = [], isLoading: isTypesLoading } =
		useEntityTypes(orgContext);

	const visible = useMemo(
		() =>
			entityTypes.filter(
				(et) =>
					!isSystemEntityType(et) &&
					(!et.organization_slug || et.organization_slug === ownerSlug),
			),
		[entityTypes, ownerSlug],
	);

	return { visible, isTypesLoading };
}

