58		});
59		const routeTree = rootRoute.addChildren([
60			ownerRoute.addChildren([
61				createRoute({ getParentRoute: () => ownerRoute, path: "/" }),
62				memoryRoute,
63				createRoute({ getParentRoute: () => ownerRoute, path: "connectors" }),
64				agentRoute.addChildren([
