66					createRoute({ getParentRoute: () => agentRoute, path: "behaviors" }),
67					createRoute({ getParentRoute: () => agentRoute, path: "settings" }),
68				]),
69			]),
70		]);
71		const router = createRouter({
72			routeTree,
73			history: createMemoryHistory({ initialEntries: [path] }),
74		});
