import { Link, Outlet, useLocation, useNavigate } from "@tanstack/react-router";
import {
	ListChecks,
	Lock,
	MessageSquare,
	Settings as SettingsIcon,
	Shield,
	Sparkles,
} from "lucide-react";
import { type ComponentType, useEffect } from "react";
import {
	AgentEditorForm,
	type AgentSection,
} from "@/components/agents/agent-editor-form";
import { AgentWorkbenchHeaderSkeleton } from "@/components/agents/agent-loading-shells";
import { ProposalReviewShell } from "@/components/agents/proposal-review-shell";
import { useCurrentOrg } from "@/hooks/use-current-org";
import { useMembers } from "@/hooks/use-members";
import { useOrgContext } from "@/hooks/use-org-context";
import {
	isAgentSkillsSubPage,
	isAgentSkillsTab,
} from "@/lib/agent-chat-routes";
import { agentTabLink } from "@/lib/agent-tab-links";
import {
	type AgentItem,
	useAgents,
	useResolvedPath,
	useSystemAgentId,
} from "@/lib/api";
import { useAuthState } from "@/lib/auth-state";
import { cn } from "@/lib/utils";

export type AgentTab = "chat" | "behaviors" | AgentSection;

const AGENT_TABS: readonly AgentTab[] = [
	"chat",
	"behaviors",
	"identity",
	"skills",
	"guardrails",
	"permissions",
	"settings",
];

export function parseAgentTab(value: unknown): AgentTab | undefined {
	return typeof value === "string" &&
		(AGENT_TABS as readonly string[]).includes(value)
		? (value as AgentTab)
		: undefined;
}

const TAB_META: {
	tab: AgentTab;
	label: string;
	icon: ComponentType<{ className?: string }>;
}[] = [
	// Chat / Behaviors / Skills are sidebar rows now — this strip is the
	// configuration surface reached from the single Settings row.
	{ tab: "settings", label: "General", icon: SettingsIcon },
	{ tab: "identity", label: "Identity", icon: Fingerprint },
	{ tab: "guardrails", label: "Guardrails", icon: Shield },
	{ tab: "permissions", label: "Permissions", icon: Lock },
];



function TabLink({
	owner,
	agentId,
	tab,
	label,
	icon: Icon,
	activeTab,
}: {
	owner: string;
	agentId: string;
	tab: AgentTab;
	label: string;
	icon: ComponentType<{ className?: string }>;
	activeTab: AgentTab;
}) {
	const link = agentTabLink(owner, agentId, tab);
	const active = activeTab === tab;
	// Same density as Home's "New conversation" / "Configure" row — active tab
	// brightens; no second-row underline strip.
	return (
		<Link
			{...link}
			className={cn(
				"inline-flex shrink-0 items-center gap-1.5 rounded-md px-2 py-1 text-sm transition-colors",
				active
					? "font-semibold text-foreground"
					: "text-muted-foreground hover:bg-muted/60 hover:text-foreground",
			)}
		>
			<Icon className="h-4 w-4 shrink-0" />
			{label}
		</Link>
	);
}

function AgentHeaderTabs({
	owner,
	agentId,
	activeTab,
}: {
	owner: string;
	agentId: string;
	activeTab: AgentTab;
}) {
	// The Permissions tab reads/writes the org-scoped write-gate envelope; its
	// endpoints require org settings admin. Hide it from regular members so they
	// never land on a 403 error state (they'd have no way to load or save it).
	const { orgContext } = useOrgContext();
	const { isAdmin } = useMembers(orgContext.organizationId);
	const tabs = isAdmin
		? TAB_META
		: TAB_META.filter(({ tab }) => tab !== "permissions");
	return (
		<>
			{tabs.map(({ tab, label, icon }) => (
				<TabLink
					key={tab}
					owner={owner}
					agentId={agentId}
					tab={tab}
					label={label}
					icon={icon}
					activeTab={activeTab}
				/>
			))}
		</>
	);
}



export function AgentsWorkbenchLayout({
	owner,
	agentId,
}: {
	owner: string;
	agentId: string;
}) {
	const navigate = useNavigate();
	const { pathname } = useLocation();
	const { isAuthenticated } = useAuthState();
	const { isMember } = useCurrentOrg();
	const canManageWorkspace = isAuthenticated && isMember;
	const { data: agents = [], isLoading: isAgentsLoading } = useAgents({
		enabled: canManageWorkspace,
	});
	useSystemAgentId({
		enabled: canManageWorkspace,
	});

	const selectedAgent = agents.find((a) => a.agentId === agentId) ?? null;
	const agentNotFound =
		!selectedAgent && !isAgentsLoading && canManageWorkspace;

	const chatPrefix = `/${owner}/agents/${agentId}/chat`;
	const conversationsPrefix = `/${owner}/agents/${agentId}/conversations`;
	const isAgentChat =
		pathname === chatPrefix || pathname.startsWith(`${chatPrefix}/`);
	// Inbound platform conversations (e.g. a Slack thread) live on their own
	// /conversations/$id route with no dedicated tab. Surface them under Chat
	// instead of letting the activeTab fallback default them to Watchers.
	const isAgentConversation =
		pathname === conversationsPrefix ||
		pathname.startsWith(`${conversationsPrefix}/`);
	const isChat = isAgentChat || isAgentConversation;
	const agentBase = `/${owner}/agents/${agentId}`;
	const isBehaviorsTab =
		pathname === `${agentBase}/behaviors` ||
		pathname.startsWith(`${agentBase}/behaviors/`);
	const isIdentityTab =
		pathname === `${agentBase}/identity` ||
		pathname === `${agentBase}/identity/`;
	const isSettingsTab =
		pathname === `${agentBase}/settings` ||
		pathname === `${agentBase}/settings/`;
	const isSkillsTab =
		isAgentSkillsTab(owner, agentId, pathname) ||
		isAgentSkillsSubPage(owner, agentId, pathname);
	const agentConfigTab = pathname.match(
		`/${owner}/agents/${agentId}/([^/]+)`,
	)?.[1];
	const activeTab: AgentTab = isChat
		? "chat"
		: isBehaviorsTab
			? "behaviors"
			: isSkillsTab
				? "skills"
				: isIdentityTab
					? "identity"
					: isSettingsTab
						? "settings"
						: (parseAgentTab(agentConfigTab) ?? "behaviors");

	useEffect(() => {
		if (agentNotFound) {
			void navigate({ to: "/$owner", params: { owner }, replace: true });
		}
	}, [agentNotFound, navigate, owner]);

	const headerReady = selectedAgent !== null;

	return (
		<div className="flex min-h-0 flex-1 flex-col gap-3 overflow-hidden py-4 md:py-6">
			{/* Single header row matching Home: identity + actions/tabs wrap together. */}
			<div className="flex shrink-0 flex-col items-center px-4 lg:px-6">
				{headerReady ? (
					<div className="flex min-w-0 max-w-full flex-wrap items-center justify-center gap-x-2 gap-y-1">
						<AgentHeaderTabs
							owner={owner}
							agentId={agentId}
							activeTab={activeTab}
						/>
					</div>
				) : (
					<AgentWorkbenchHeaderSkeleton />
				)}
			</div>

			<div
				className={cn(
					"flex min-h-0 min-w-0 flex-1 flex-col px-4 lg:px-6",
					isChat ? "overflow-hidden" : "overflow-y-auto",
				)}
			>
				<Outlet />
			</div>
		</div>
	);
}

export function AgentConfigPane({
	agent,
	tab,
	runId,
}: {
	agent: AgentItem;
	tab: AgentSection;
	/** Slack config-approval deep link `?run_id`; when set, the ProposalReviewShell
	 *  fetches the held builder proposal and the form prefills it for review. */
	runId?: number;
}) {
	return (
		<div className="mx-auto w-full max-w-3xl pb-6">
			<ProposalReviewShell
				resource={{ kind: "agent", agentId: agent.agentId }}
				runId={runId}
			>
				{({ reviewMode, proposal, controlsDisabled }) => (
					<AgentEditorForm
						key={agent.agentId}
						mode={{ kind: "edit", agent }}
						section={tab}
						reviewMode={reviewMode}
						reviewProposal={proposal}
						reviewControlsDisabled={controlsDisabled}
					/>
				)}
			</ProposalReviewShell>
		</div>
	);
}

export function AgentConfigRoute({
	owner,
	agentId,
	tab,
	runId,
}: {
	owner: string;
	agentId: string;
	tab: AgentSection;
	runId?: number;
}) {
	const { orgContext, hasOrgContext } = useOrgContext();
	const { isLoading: isResolvedLoading } = useResolvedPath(
		`/${owner}`,
		orgContext,
	);
	const { isAuthenticated } = useAuthState();
	const { isMember, isLoading: isOrgLoading } = useCurrentOrg();
	const canManageWorkspace = isAuthenticated && isMember;
	const { data: agents = [], isLoading: isAgentsLoading } = useAgents({
		enabled: canManageWorkspace,
	});
	const isLoading = canManageWorkspace
		? !hasOrgContext || isResolvedLoading || isAgentsLoading || isOrgLoading
		: isResolvedLoading || isOrgLoading;

	const selectedAgent = agents.find((a) => a.agentId === agentId) ?? null;

	if (isLoading || !selectedAgent) {
		return null;
	}

	return <AgentConfigPane agent={selectedAgent} tab={tab} runId={runId} />;
}

