import { parseRunId } from "@/components/agents/config-prefill";
import { useAgents, useWorkspaceRoot } from "@/lib/api";

export const Route = createFileRoute("/$owner/agents/$agentId/identity")({
	validateSearch: (search: Record<string, unknown>) => ({
		// Slack config-approval deep link: `?run_id=42` prefills the form with the
		// held builder proposal for review (Approve/Reject) instead of a plain edit.
		// URL params arrive as strings, so coerce and drop anything non-numeric.
		run_id: parseRunId(search.run_id),
	}),
	loader: ({ context: { queryClient }, params }) => {
		void queryClient.prefetchQuery(
			useWorkspaceRoot.queryOptions(params.owner, { slug: params.owner }),
		);
		void queryClient.prefetchQuery(useAgents.queryOptions(params.owner));
	},
	component: AgentIdentityPage,
});

