import { Outlet, useLocation, useNavigate } from "@tanstack/react-router";
import { useEffect } from "react";
import {
	AgentEditorForm,
	type AgentSection,
} from "@/components/agents/agent-editor-form";
import { ProposalReviewShell } from "@/components/agents/proposal-review-shell";
import { useCurrentOrg } from "@/hooks/use-current-org";
import { useOrgContext } from "@/hooks/use-org-context";
import {
	type AgentItem,
	useAgents,
	useResolvedPath,
	useSystemAgentId,
} from "@/lib/api";
import { useAuthState } from "@/lib/auth-state";
import { cn } from "@/lib/utils";

export type AgentTab = "chat" | "behaviors" | AgentSection;

const AGENT_TABS: readonly AgentTab[] = [
	"chat",
	"behaviors",
	"identity",
	"skills",
	"guardrails",
	"settings",
];

export function parseAgentTab(value: unknown): AgentTab | undefined {
	return typeof value === "string" &&
		(AGENT_TABS as readonly string[]).includes(value)
		? (value as AgentTab)
		: undefined;
}

export function AgentsWorkbenchLayout({
	owner,
	agentId,
}: {
	owner: string;
	agentId: string;
}) {
	const navigate = useNavigate();
	const { pathname } = useLocation();
	const { isAuthenticated } = useAuthState();
	const { isMember } = useCurrentOrg();
	const canManageWorkspace = isAuthenticated && isMember;
	const { data: agents = [], isLoading: isAgentsLoading } = useAgents({
		enabled: canManageWorkspace,
	});
	useSystemAgentId({
		enabled: canManageWorkspace,
	});

	const selectedAgent = agents.find((a) => a.agentId === agentId) ?? null;
	const agentNotFound =
		!selectedAgent && !isAgentsLoading && canManageWorkspace;

	const chatPrefix = `/${owner}/agents/${agentId}/chat`;
	const conversationsPrefix = `/${owner}/agents/${agentId}/conversations`;
	const isAgentChat =
		pathname === chatPrefix || pathname.startsWith(`${chatPrefix}/`);
	// Inbound platform conversations (e.g. a Slack thread) live on their own
	// /conversations/$id route with no dedicated tab. Surface them under Chat
	// instead of letting the activeTab fallback default them to Watchers.
	const isAgentConversation =
		pathname === conversationsPrefix ||
		pathname.startsWith(`${conversationsPrefix}/`);
	const isChat = isAgentChat || isAgentConversation;
	useEffect(() => {
		if (agentNotFound) {
			void navigate({ to: "/$owner", params: { owner }, replace: true });
		}
	}, [agentNotFound, navigate, owner]);

	return (
		<div className="flex min-h-0 flex-1 flex-col gap-3 overflow-hidden py-4 md:py-6">
			{/* No tab strip: Chat, Behaviors, Skills, Guardrails and Settings are all
			    sidebar rows under the agent, so a strip here would be a second copy
			    of the same navigation. */}
			<div
				className={cn(
					"flex min-h-0 min-w-0 flex-1 flex-col px-4 lg:px-6",
					isChat ? "overflow-hidden" : "overflow-y-auto",
				)}
			>
				<Outlet />
			</div>
		</div>
	);
}

export function AgentConfigPane({
	agent,
	tab,
	runId,
}: {
	agent: AgentItem;
	tab: AgentSection;
	/** Slack config-approval deep link `?run_id`; when set, the ProposalReviewShell
	 *  fetches the held builder proposal and the form prefills it for review. */
	runId?: number;
}) {
	return (
		<div className="mx-auto w-full max-w-3xl pb-6">
			<ProposalReviewShell
				resource={{ kind: "agent", agentId: agent.agentId }}
				runId={runId}
			>
				{({ reviewMode, proposal, controlsDisabled }) => (
					<AgentEditorForm
						key={agent.agentId}
						mode={{ kind: "edit", agent }}
						section={tab}
						reviewMode={reviewMode}
						reviewProposal={proposal}
						reviewControlsDisabled={controlsDisabled}
					/>
				)}
			</ProposalReviewShell>
		</div>
	);
}

export function AgentConfigRoute({
	owner,
	agentId,
	tab,
	runId,
}: {
	owner: string;
	agentId: string;
	tab: AgentSection;
	runId?: number;
}) {
	const { orgContext, hasOrgContext } = useOrgContext();
	const { isLoading: isResolvedLoading } = useResolvedPath(
		`/${owner}`,
		orgContext,
	);
	const { isAuthenticated } = useAuthState();
	const { isMember, isLoading: isOrgLoading } = useCurrentOrg();
	const canManageWorkspace = isAuthenticated && isMember;
	const { data: agents = [], isLoading: isAgentsLoading } = useAgents({
		enabled: canManageWorkspace,
	});
	const isLoading = canManageWorkspace
		? !hasOrgContext || isResolvedLoading || isAgentsLoading || isOrgLoading
		: isResolvedLoading || isOrgLoading;

	const selectedAgent = agents.find((a) => a.agentId === agentId) ?? null;

	if (isLoading || !selectedAgent) {
		return null;
	}

	return <AgentConfigPane agent={selectedAgent} tab={tab} runId={runId} />;
}

import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import {
	createMemoryHistory,
	createRootRoute,
	createRoute,
	createRouter,
	RouterProvider,
} from "@tanstack/react-router";
import { render, screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import { AppSidebar } from "./app-sidebar";

// The sidebar is pure nav over hook-provided data — pin the data so the test
// exercises only the site-map structure (expansion + link targets).
vi.mock("@/hooks/use-working-agents", () => ({
	useWorkingAgents: () => ({
		rosterAgents: [
			{ agentId: "agent-a", name: "Alpha", status: "idle" as const },
			{ agentId: "agent-b", name: "Beta", status: "idle" as const },
		],
		workingAgents: [],
		systemAgentId: null,
		isLoading: false,
	}),
}));

vi.mock("@/hooks/use-org-context", () => ({
	useOrgContext: () => ({ currentOwner: "test-org" }),
}));

vi.mock("@/lib/auth-state", () => ({
	useAuthState: () => ({ session: null }),
}));

vi.mock("@/components/sidebar/organization-dropdown", () => ({
	OrganizationDropdown: () => <div data-testid="org-dropdown" />,
}));

/**
 * Minimal route tree covering every path the sidebar links to, with the
 * sidebar mounted at the root so `useLocation` / `useParams` see the real
 * route context.
 */
async function renderSidebarAt(path: string) {
	const rootRoute = createRootRoute({ component: () => <AppSidebar /> });
	const ownerRoute = createRoute({
		getParentRoute: () => rootRoute,
		path: "/$owner",
	});
	const agentRoute = createRoute({
		getParentRoute: () => ownerRoute,
		path: "agents/$agentId",
	});
	const memoryRoute = createRoute({
		getParentRoute: () => ownerRoute,
		path: "memory",
		validateSearch: (s: Record<string, unknown>) => s,
	});
	const routeTree = rootRoute.addChildren([
		ownerRoute.addChildren([
			createRoute({ getParentRoute: () => ownerRoute, path: "/" }),
			memoryRoute,
			createRoute({ getParentRoute: () => ownerRoute, path: "connectors" }),
			agentRoute.addChildren([
				createRoute({ getParentRoute: () => agentRoute, path: "chat" }),
				createRoute({ getParentRoute: () => agentRoute, path: "behaviors" }),
				createRoute({ getParentRoute: () => agentRoute, path: "settings" }),
			]),
		]),
	]);
	const router = createRouter({
		routeTree,
		history: createMemoryHistory({ initialEntries: [path] }),
	});
	const queryClient = new QueryClient({
		defaultOptions: { queries: { retry: false } },
	});
	render(
		<QueryClientProvider client={queryClient}>
			{/* biome-ignore lint/suspicious/noExplicitAny: synthetic test router */}
			<RouterProvider router={router as any} />
		</QueryClientProvider>,
	);
	// Both agent rows mounting proves the router matched and the tree settled.
	await screen.findByText("Alpha");
	await screen.findByText("Beta");
}

describe("AppSidebar site map", () => {
	it("expands only the route-active agent to Behaviors/Settings (no Chat child)", async () => {
		await renderSidebarAt("/test-org/agents/agent-a/chat");

		expect(screen.queryByRole("link", { name: "Chat" })).toBeNull();
		const behaviors = screen.getByRole("link", { name: "Behaviors" });
		const settings = screen.getByRole("link", { name: "Settings" });
		expect(behaviors).toHaveAttribute(
			"href",
			"/test-org/agents/agent-a/behaviors",
		);
		expect(settings).toHaveAttribute(
			"href",
			"/test-org/agents/agent-a/settings",
		);
		expect(screen.getByRole("link", { name: /Alpha/ })).toHaveAttribute(
			"href",
			"/test-org/agents/agent-a/chat",
		);
	});

	it("renders no agent children when no agent route is active", async () => {
		await renderSidebarAt("/test-org/memory");

		expect(screen.queryByRole("link", { name: "Behaviors" })).toBeNull();
		expect(screen.queryByRole("link", { name: "New chat" })).toBeNull();
	});

	it("links Connect straight to /connectors", async () => {
		await renderSidebarAt("/test-org/connectors");

		expect(screen.getByRole("link", { name: "Connect" })).toHaveAttribute(
			"href",
			"/test-org/connectors",
		);
	});

	// Activity = Memory Events; Context = the entity schema. Not a /activity page.
	it("links Activity to /memory and Context to /memory?view=entities", async () => {
		await renderSidebarAt("/test-org/memory");

		expect(screen.getByRole("link", { name: "Activity" })).toHaveAttribute(
			"href",
			"/test-org/memory",
		);
		expect(screen.getByRole("link", { name: "Context" })).toHaveAttribute(
			"href",
			"/test-org/memory?view=entities",
		);
		// This row was "Models" (collided with model *providers* under Connect),
		// then "Entities". Neither old label may survive anywhere in the nav.
		expect(screen.queryByRole("link", { name: "Models" })).toBeNull();
		expect(screen.queryByRole("link", { name: "Entities" })).toBeNull();
	});
});

