import { Link, useNavigate } from "@tanstack/react-router";
import {
	Background,
	BackgroundVariant,
	Controls,
	type Edge,
	Handle,
	MarkerType,
	type Node,
	type NodeProps,
	Position,
	ReactFlow,
	useNodesState,
} from "@xyflow/react";
import { Boxes, Pencil, Spline } from "lucide-react";
import {
	type CSSProperties,
	useCallback,
	useEffect,
	useMemo,
	useState,
} from "react";
import { useMembers } from "@/hooks/use-members";
import { useOrgContext } from "@/hooks/use-org-context";
import {
	TabEmptyState,
	TabErrorState,
} from "@/components/entity-tabs/tab-states";
import { Button } from "@/components/ui/button";
import { EntityIcon } from "@/components/ui/entity-icon";
import { Skeleton } from "@/components/ui/skeleton";
import {
	memoryBrowseTypeSearch,
	memoryCreateEntityTypeSearch,
} from "@/lib/memory-browse";
import { cn } from "@/lib/utils";
import { labelledEdgeIds, type SchemaNodeData } from "./entity-schema-graph";
import { NewRelationshipDialog } from "./new-relationship-dialog";
import { useEntitySchemaGraph } from "./use-entity-schema-graph";

import "@xyflow/react/dist/style.css";

// React Flow v12 constrains node data to `Record<string, unknown>`. Widen only
// at this boundary — adding an index signature to `SchemaNodeData` itself would
// make every mistyped field access compile.
type SchemaFlowNode = Node<
	SchemaNodeData & Record<string, unknown>,
	"entityType"
>;

function handleOffset(index: number, count: number): string {
	return `${((index + 1) / (count + 1)) * 100}%`;
}

/**
 * One entity type, drawn as a database-style table box: a header with the icon
 * and name, then its `metadata_schema` fields. Clicking opens that type's
 * records, the same destination the list view navigated to.
 */
function EntityTypeNode({ data, width, height }: NodeProps<SchemaFlowNode>) {
	return (
		<div className="group/node relative" style={{ width, height }}>
			{data.targetHandleIds.map((handleId, index) => (
				<Handle
					key={handleId}
					id={handleId}
					type="target"
					position={Position.Left}
					style={{ top: handleOffset(index, data.targetHandleIds.length) }}
					className="!border-0 !bg-muted-foreground/40"
				/>
			))}
			{data.selfTargetHandleIds.map((handleId, index) => (
				<Handle
					key={handleId}
					id={handleId}
					type="target"
					position={Position.Top}
					style={{
						left: handleOffset(index, data.selfTargetHandleIds.length),
					}}
					className="!border-0 !bg-muted-foreground/40"
				/>
			))}
			{data.sourceHandleIds.map((handleId, index) => (
				<Handle
					key={handleId}
					id={handleId}
					type="source"
					position={Position.Right}
					style={{ top: handleOffset(index, data.sourceHandleIds.length) }}
					className="!border-0 !bg-muted-foreground/40"
				/>
			))}

			<button
				type="button"
				aria-label={`Browse ${data.label} records`}
				className={cn(
					"h-full w-full cursor-pointer overflow-hidden rounded-lg border bg-card text-left shadow-sm transition-colors",
					"hover:border-primary/60 hover:shadow-md",
					"focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring",
					// Reserved `$…` types are shown but visually set apart so an
					// intentionally empty schema does not look broken.
					data.isSystem &&
						"border-dashed border-muted-foreground/40 bg-muted/40",
				)}
			>
				<span className="flex h-full items-center gap-2 px-3">
					<EntityIcon icon={data.icon} className="h-4 w-4 shrink-0" />
					<span className="min-w-0 flex-1 truncate text-sm font-semibold text-foreground">
						{data.label}
					</span>
					{/* Boxes still say how much schema is behind them, so a header-only
					    box never reads as a type with no fields. */}
					{data.fields.length > 0 ? (
						<span className="shrink-0 text-[11px] tabular-nums text-muted-foreground/60">
							{data.fields.length}f
						</span>
					) : null}
					{typeof data.entityCount === "number" ? (
						<span className="shrink-0 pr-5 text-[11px] tabular-nums text-muted-foreground">
							{data.entityCount}
						</span>
					) : null}
				</span>
			</button>

			{/* Sibling of the browse button, not a child — a button cannot nest a
			    link. Schema editing (fields, relationships) lives in the existing
			    entity-type form; this is the way in from the map. */}
			<Link
				to="/$owner/entity-types/$slug"
				params={{ owner: data.ownerSlug, slug: data.slug }}
				aria-label={`Edit ${data.label} schema`}
				title="Edit schema"
				onClick={(event) => event.stopPropagation()}
				className={cn(
					"absolute right-2 top-2.5 rounded p-1 text-muted-foreground/70 opacity-0 transition",
					"hover:bg-accent hover:text-foreground focus-visible:opacity-100",
					"focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring",
					"group-hover/node:opacity-100",
				)}
			>
				<Pencil className="h-3 w-3" />
			</Link>
		</div>
	);
}

const NODE_TYPES = { entityType: EntityTypeNode };

/**
 * Merge a freshly built graph into the nodes React Flow is currently showing,
 * keeping any position the user dragged a box to.
 *
 * Returns `current` unchanged when nothing rendered differs. That bail-out is
 * load bearing: the hook hands back a brand-new graph object every render (its
 * `rulesBySlug` comes from `useQueries`' combine), so a resync that always
 * produced a new array would be an infinite setState/render loop.
 *
 * Everything except position is compared, rather than a hand-listed subset —
 * a whitelist silently goes stale the moment a field is added to the node, and
 * has already caused renamed types and refreshed counts to keep displaying old
 * values.
 */
function mergeGraphIntoNodes(
	current: SchemaFlowNode[],
	next: SchemaFlowNode[],
): SchemaFlowNode[] {
	const byId = new Map(current.map((node) => [node.id, node]));
	let changed = current.length !== next.length;

	const merged = next.map((node, index) => {
		const existing = byId.get(node.id);
		if (!existing || current[index]?.id !== node.id) {
			changed = true;
			return node;
		}
		// Keep where the user put it; take everything else from the rebuild.
		const candidate: SchemaFlowNode = { ...node, position: existing.position };
		if (renderedStateOf(existing) === renderedStateOf(candidate)) return existing;
		changed = true;
		return candidate;
	});

	return changed ? merged : current;
}

/** Everything about a node that affects what is drawn or where it links. */
function renderedStateOf(node: SchemaFlowNode): string {
	const { position: _position, ...rest } = node;
	return JSON.stringify(rest);
}

/**
 * Entities tab body when no type is scoped: an ERD of the workspace schema.
 *
 * Nodes are not directly editable. Clicking one opens its records, its pencil
 * opens the existing schema form, and the toolbar can add a declared
 * relationship. Boxes can be dragged to untangle a dense area, but positions
 * are not persisted — a reload returns to dagre's layout.
 */
export function EntityTypeGraphView({ ownerSlug }: { ownerSlug: string }) {
	const navigate = useNavigate();
	const { orgContext } = useOrgContext();
	// Schema authoring (`create`, `add_rule`) is in OWNER_ADMIN_ACTIONS, while
	// reading the map is public-read. Offering these to a member would only get
	// them an authorization failure after they filled the dialog in.
	const { isAdmin } = useMembers(orgContext.organizationId);
	const [addingRelationship, setAddingRelationship] = useState(false);
	// Boxes are headers only: the map is about how types relate, and full field
	// lists on every box drown the edges out. Fields live in the type's editor.
	const { graph, isLoading, isError, hasTypes } = useEntitySchemaGraph(ownerSlug);

	const laidOutNodes = useMemo<SchemaFlowNode[]>(
		() =>
			graph.nodes.map((node) => ({
				id: node.id,
				type: "entityType" as const,
				position: node.position,
				width: node.width,
				height: node.height,
				// Spread so the literal satisfies React Flow's `Record<string, unknown>`
				// data constraint without loosening `SchemaNodeData`.
				data: { ...node.data },
			})),
		[graph.nodes],
	);

	// Dragging needs mutable node state, so React Flow owns positions once the
	// canvas mounts. Nothing is persisted — a reload returns to dagre's layout.
	const [nodes, setNodes, onNodesChange] = useNodesState(laidOutNodes);

	// `useNodesState` seeds from its argument once, so a rebuilt graph — a
	// renamed type, a new relationship, a refreshed entity count — has to be
	// pushed in. See `mergeGraphIntoNodes` for why it must bail out when nothing
	// rendered actually changed.
	useEffect(() => {
		setNodes((current) => mergeGraphIntoNodes(current, laidOutNodes));
	}, [laidOutNodes, setNodes]);

	const edges = useMemo<Edge[]>(() => {
		const labelled = labelledEdgeIds(graph.edges);
		return graph.edges.map((edge) => {
			return {
				id: edge.id,
				source: edge.source,
				target: edge.target,
				sourceHandle: `${edge.id}-source`,
				targetHandle: `${edge.id}-target`,
				label: labelled.has(edge.id) ? edge.data.label : undefined,
				className: "text-muted-foreground",
				// A symmetric relation is an unordered pair, so an arrowhead would
				// assert a direction the data does not have.
				markerEnd: edge.data.isSymmetric
					? undefined
					: { type: MarkerType.ArrowClosed, width: 14, height: 14 },
			};
		});
	}, [graph.edges]);

	const endpointOptions = useMemo(
		() =>
			graph.nodes
				.map((node) => ({ slug: node.data.slug, label: node.data.label })),
		[graph.nodes],
	);

	// No drag/click disambiguation is needed: the browser does not emit a click
	// after a press that moved the pointer (verified in-browser — a drag fires
	// pointerdown/pointerup and no click), so React Flow never turns a drag into
	// an `onNodeClick`.
	const handleNodeClick = useCallback(
		(_: unknown, node: SchemaFlowNode) => {
			void navigate(
				memoryBrowseTypeSearch(ownerSlug, node.data.slug, { view: "entities" }),
			);
		},
		[navigate, ownerSlug],
	);

	if (isLoading) {
		return (
			<div
				role="status"
				aria-label="Loading workspace schema"
				className="flex min-h-0 w-full flex-1 flex-col"
			>
				<Skeleton className="min-h-[420px] w-full flex-1 rounded-lg" />
			</div>
		);
	}

	if (isError) {
		return <TabErrorState label="workspace schema" />;
	}

	if (!hasTypes) {
		return (
			<TabEmptyState
				icon={Boxes}
				title="No entity types yet"
				description={
					isAdmin
						? "Entity types define the records Memory can track — companies, people, tickets, and anything else you model. Create a type to get started."
						: "Entity types define the records Memory can track. An admin can add the first one."
				}
				actionLabel={isAdmin ? "Create entity type" : undefined}
				onAction={
					isAdmin
						? () => void navigate(memoryCreateEntityTypeSearch(ownerSlug))
						: undefined
				}
			/>
		);
	}

	return (
		// Full width, not a centered reading column: a schema map is only as useful
		// as the space it gets, and the diagram grows with the workspace.
		<div className="flex min-h-0 w-full flex-1 flex-col gap-3">
			<div className="flex flex-wrap items-center justify-between gap-3">
				<p className="text-sm text-muted-foreground">
					{graph.edges.length > 0
						? "Your workspace schema. Click a type to browse its records, or edit one to change its fields and relationships."
						: "Your workspace schema. Click a type to browse its records — relationships appear here once you add one to a type."}
				</p>
				{isAdmin ? (
					<div className="flex shrink-0 items-center gap-2">
						<Button
							type="button"
							variant="outline"
							size="sm"
							className="h-8 text-xs"
							onClick={() => setAddingRelationship(true)}
						>
							<Spline className="mr-1.5 h-3.5 w-3.5" />
							New relationship
						</Button>
						<Button
							type="button"
							variant="outline"
							size="sm"
							className="h-8 text-xs"
							onClick={() =>
								void navigate(memoryCreateEntityTypeSearch(ownerSlug))
							}
						>
							Create entity type
						</Button>
					</div>
				) : null}
			</div>

			<div className="min-h-[420px] w-full flex-1 overflow-hidden">
				<ReactFlow
					nodes={nodes}
					edges={edges}
					nodeTypes={NODE_TYPES}
					onNodesChange={onNodesChange}
					onNodeClick={handleNodeClick}
					fitView
					// Open at 1:1 so labels are readable on arrival rather than shrunk
					// to fill the pane. `minZoom` floors the auto-fit well above the
					// manual floor: a big schema still shrinks somewhat to show its
					// shape, but never past readable, and pans for the rest.
					fitViewOptions={{ minZoom: 0.7, maxZoom: 1, padding: 0.15 }}
					// Boxes can be rearranged to untangle a dense area. Positions are
					// not persisted — a reload returns to dagre's layout.
					nodesDraggable
					nodesConnectable={false}
					nodesFocusable={false}
					edgesFocusable={false}
					proOptions={{ hideAttribution: true }}
					minZoom={0.2}
					maxZoom={1.5}
					className="bg-background"
					// xyflow defaults edge labels and the zoom controls to hardcoded
					// white, which reads as a light patch on the canvas and is unusable
					// in dark mode. These are its own theming variables, so drive them
					// from the theme tokens rather than overriding the generated rules.
					style={
						{
							"--xy-edge-label-background-color": "var(--background)",
							"--xy-edge-label-color": "var(--muted-foreground)",
							"--xy-controls-button-background-color": "var(--card)",
							"--xy-controls-button-background-color-hover": "var(--accent)",
							"--xy-controls-button-color": "var(--muted-foreground)",
							"--xy-controls-button-color-hover": "var(--foreground)",
							"--xy-controls-button-border-color": "var(--border)",
							"--xy-controls-box-shadow": "0 1px 2px 0 rgb(0 0 0 / 0.05)",
						} as CSSProperties
					}
				>
					<Background variant={BackgroundVariant.Dots} gap={16} size={1} />
					<Controls showInteractive={false} />
				</ReactFlow>
			</div>

			{/* Gated on its own, not just on the trigger being hidden — the dialog
			    drives admin-only mutations regardless of how it was opened. */}
			{isAdmin ? (
				<NewRelationshipDialog
					open={addingRelationship}
					onOpenChange={setAddingRelationship}
					entityTypes={endpointOptions}
				/>
			) : null}
		</div>
	);
}

