import { type UseQueryResult, useQueries } from "@tanstack/react-query";
import { useCallback, useMemo } from "react";
import { useOrgContext } from "@/hooks/use-org-context";
import {
	type RelationshipTypeRule,
	useEntityTypes,
	useRelationshipTypeRules,
	useRelationshipTypes,
} from "@/lib/api/entities";
import {
	buildLaidOutSchemaGraph,
	type RulesBySlug,
	selectRelationshipTypesForGraph,
} from "./entity-schema-graph";

/**
 * Data for the entity-type ERD.
 *
 * Unlike `useVisibleEntityTypes` (rail + scope bar) this KEEPS system types —
 * `$resource` is the ACL anchor for Slack channels and GitHub repos, so it is
 * one of the more informative nodes on the map. They are flagged, not dropped,
 * and the view colors them differently.
 *
 * Rules are fetched per relationship type (`list_rules` takes one slug), so this
 * is 1+N requests where N is the unique relationship-type count. A bulk rules
 * action can replace only this hook later;
 * `buildLaidOutSchemaGraph` is pure and does not care where rules came from.
 */
export function useEntitySchemaGraph(ownerSlug: string) {
	const { orgContext, hasOrgContext } = useOrgContext();
	const {
		data: entityTypes = [],
		isLoading: isTypesLoading,
		isError: isTypesError,
	} = useEntityTypes(orgContext);
	const {
		data: relationshipTypes = [],
		isLoading: isRelTypesLoading,
		isError: isRelTypesError,
	} = useRelationshipTypes(orgContext);

	const scopedTypes = useMemo(
		() =>
			entityTypes.filter(
				(et) => !et.organization_slug || et.organization_slug === ownerSlug,
			),
		[entityTypes, ownerSlug],
	);

	const resolvedRelationshipTypes = useMemo(
		() => selectRelationshipTypesForGraph(relationshipTypes),
		[relationshipTypes],
	);

	const combineRuleQueries = useCallback(
		(results: UseQueryResult<RelationshipTypeRule[]>[]) => {
			const bySlug: RulesBySlug = {};
			resolvedRelationshipTypes.forEach((rt, idx) => {
				const rules = results[idx]?.data;
				if (rules?.length) bySlug[rt.slug] = rules;
			});
			return {
				rulesBySlug: bySlug,
				isRulesLoading: results.some((result) => result.isLoading),
				isRulesError: results.some((result) => result.isError),
			};
		},
		[resolvedRelationshipTypes],
	);

	// One `list_rules` per relationship type, run in parallel. `useQueries` takes
	// a dynamic-length list, so the query count can track the type count without
	// violating the rules of hooks.
	//
	// `.queryOptions()` does not carry the hook's `enabled` predicate, so gate
	// explicitly when there is no org context.
	const { rulesBySlug, isRulesLoading, isRulesError } = useQueries({
		queries: resolvedRelationshipTypes.map((rt) => ({
			...useRelationshipTypeRules.queryOptions(rt.slug, orgContext),
			enabled: hasOrgContext,
		})),
		// Fold the per-slug results in `combine` so the returned map is memoized on
		// the query results themselves. The callback must also be stable: TanStack
		// recomputes a combined result when the function identity changes.
		// Only derive rule-query state here. Entity types are not inputs to
		// `combine`, so graph construction belongs in the `useMemo` below.
		combine: combineRuleQueries,
	});

	const graph = useMemo(
		() =>
			buildLaidOutSchemaGraph({
				entityTypes: scopedTypes,
				relationshipTypes: resolvedRelationshipTypes,
				rulesBySlug,
				ownerSlug,
			}),
		[scopedTypes, resolvedRelationshipTypes, rulesBySlug, ownerSlug],
	);

	return {
		graph,
		// Edges arrive after nodes; treat the canvas as loading until rules settle
		// so the diagram never flashes a disconnected set of boxes.
		isLoading: isTypesLoading || isRelTypesLoading || isRulesLoading,
		isError: isTypesError || isRelTypesError || isRulesError,
		hasTypes: scopedTypes.length > 0,
	};
}

===== entity-schema-graph.ts =====
import dagre from "dagre";
import type {
	EntityType,
	RelationshipType,
	RelationshipTypeRule,
} from "@/lib/api";
import { isSystemEntityType } from "@/lib/reserved";

/**
 * Pure model + layout for the entity-type ERD.
 *
 * Boxes are entity TYPES (not rows); edges are the DECLARED
 * `entity_relationship_type_rules` (source→target slug pairs), so the diagram
 * renders correctly even for an org with zero entity rows. Kept free of React
 * and of the data-fetching layer so the shape logic is unit-testable and the
 * rules source can change (per-slug fan-out today, a bulk endpoint later)
 * without touching the view.
 */

/** A field row rendered inside a type's box. */
export interface SchemaNodeField {
	name: string;
	/** JSON-schema type, when the property declares one. */
	type?: string;
}

export interface SchemaNodeData {
	slug: string;
	label: string;
	/** Owner slug, so a node can link straight to its entity-type editor. */
	ownerSlug: string;
	icon?: string | null;
	fields: SchemaNodeField[];
	/** Reserved `$…` type, rendered in a distinct color rather than hidden. */
	isSystem: boolean;
	entityCount?: number;
	/** Edge-specific handles keep parallel relationships from overlapping. */
	sourceHandleIds: string[];
	targetHandleIds: string[];
	/** Self-loop targets attach above the node so their paths remain visible. */
	selfTargetHandleIds: string[];
}

interface SchemaEdgeData {
	/** Relationship type slug (`works_at`), not the rule id. */
	slug: string;
	label: string;
	/** Symmetric relations render without an arrowhead — the pair is unordered. */
	isSymmetric: boolean;
}

interface SchemaGraphNode {
	id: string;
	data: SchemaNodeData;
	position: { x: number; y: number };
	width: number;
	height: number;
}

export interface SchemaGraphEdge {
	id: string;
	source: string;
	target: string;
	data: SchemaEdgeData;
}

interface SchemaGraph {
	nodes: SchemaGraphNode[];
	edges: SchemaGraphEdge[];
}

/** Rules keyed by the relationship-type slug they belong to. */
export type RulesBySlug = Record<string, RelationshipTypeRule[]>;

/**
 * Which edges should carry a visible label.
 *
 * Parallel edges between the same pair stack identical text in the same spot,
 * so only the first of a pair is labelled. Keyed by the PAIR rather than by
 * relationship type: one type can join several different pairs (`contains`
 * covers order→product and invoice→payment), and keying by type alone would
 * caption an unrelated pair with the first pair's name.
 */
export function labelledEdgeIds(edges: SchemaGraphEdge[]): Set<string> {
	const seenPairs = new Set<string>();
	const labelled = new Set<string>();
	for (const edge of edges) {
		const pairKey = `${edge.data.slug}|${edge.source}|${edge.target}`;
		if (seenPairs.has(pairKey)) continue;
		seenPairs.add(pairKey);
		labelled.add(edge.id);
	}
	return labelled;
}

const NODE_WIDTH = 220;
const HEADER_HEIGHT = 44;

function compareSlugs(a: { slug: string }, b: { slug: string }): number {
	return a.slug < b.slug ? -1 : a.slug > b.slug ? 1 : 0;
}

/**
 * Keep active relationship types only. The accessible list is tenant-first and
 * may also contain a public type with the same slug; `list_rules` resolves that
 * slug tenant-first, so keep the first type to label its rules consistently.
 */
export function selectRelationshipTypesForGraph(
	relationshipTypes: RelationshipType[],
): RelationshipType[] {
	const seen = new Set<string>();
	return relationshipTypes.filter((relationshipType) => {
		if (relationshipType.status !== "active") return false;
		if (seen.has(relationshipType.slug)) return false;
		seen.add(relationshipType.slug);
		return true;
	});
}

/**
 * Field rows for a type's box, read from its `metadata_schema` JSON-schema
 * `properties`. `$resource` is a deliberate graph anchor with an empty schema,
 * so an empty list is expected rather than a failure.
 */
export function schemaFields(entityType: EntityType): SchemaNodeField[] {
	const schema = entityType.metadata_schema;
	if (!schema || typeof schema !== "object") return [];
	const properties = (schema as Record<string, unknown>).properties;
	if (!properties || typeof properties !== "object") return [];

	return Object.entries(properties as Record<string, unknown>).map(
		([name, spec]) => {
			const type =
				spec && typeof spec === "object"
					? (spec as Record<string, unknown>).type
					: undefined;
			return { name, type: typeof type === "string" ? type : undefined };
		},
	);
}

/**
 * Build the unpositioned graph. Only rules whose BOTH endpoints resolve to a
 * known type become edges — a rule naming a deleted type would otherwise
 * produce an edge to a node that does not exist.
 */
export function buildSchemaGraph(opts: {
	entityTypes: EntityType[];
	relationshipTypes: RelationshipType[];
	rulesBySlug: RulesBySlug;
	ownerSlug: string;
}): { nodes: Omit<SchemaGraphNode, "position">[]; edges: SchemaGraphEdge[] } {
	const { entityTypes, relationshipTypes, rulesBySlug, ownerSlug } = opts;
	const orderedEntityTypes = [...entityTypes].sort(compareSlugs);
	const resolvedRelationshipTypes =
		selectRelationshipTypesForGraph(relationshipTypes).sort(compareSlugs);

	const knownSlugs = new Set(orderedEntityTypes.map((et) => et.slug));
	const edges: SchemaGraphEdge[] = [];
	const sourceHandles = new Map<string, string[]>();
	const targetHandles = new Map<string, string[]>();
	const selfTargetHandles = new Map<string, string[]>();

	for (const rt of resolvedRelationshipTypes) {
		const rules = [...(rulesBySlug[rt.slug] ?? [])].sort((a, b) => a.id - b.id);

		for (const rule of rules) {
			const source = rule.source_entity_type_slug;
			const target = rule.target_entity_type_slug;
			if (!knownSlugs.has(source) || !knownSlugs.has(target)) continue;

			const edge = {
				// Rule id keeps sibling rules of one relationship type distinct.
				id: `rule-${rule.id}`,
				source,
				target,
				data: {
					slug: rt.slug,
					label: rt.name || rt.slug,
					isSymmetric: rt.is_symmetric,
				},
			};
			edges.push(edge);
			sourceHandles.set(source, [
				...(sourceHandles.get(source) ?? []),
				`${edge.id}-source`,
			]);
			const targetHandleMap =
				source === target ? selfTargetHandles : targetHandles;
			targetHandleMap.set(target, [
				...(targetHandleMap.get(target) ?? []),
				`${edge.id}-target`,
			]);
		}
	}

	const nodes = orderedEntityTypes.map((et) => {
		const fields = schemaFields(et);
		return {
			id: et.slug,
			width: NODE_WIDTH,
			// Header-only: the diagram is about relationships, and field lists
			// compete with the edges for attention past a handful of types.
			height: HEADER_HEIGHT,
			data: {
				slug: et.slug,
				label: et.name || et.slug,
				ownerSlug,
				icon: et.icon,
				fields,
				isSystem: isSystemEntityType(et),
				entityCount: et.entity_count,
				sourceHandleIds: sourceHandles.get(et.slug) ?? [],
				targetHandleIds: targetHandles.get(et.slug) ?? [],
				selfTargetHandleIds: selfTargetHandles.get(et.slug) ?? [],
			},
		};
	});

	return { nodes, edges };
}

const MARGIN = 24;
/** Gap between the connected flow and the unconnected band beneath it. */
const BAND_GAP = 72;

/**
 * Deterministic dagre layout — same input always yields the same arrangement,
 * so positions never need persisting and a reload does not reshuffle the map.
 *
 * Only types that a rule actually touches go through dagre. Unconnected types
 * have no edge to rank them, so dagre packs them into the first column, which
 * stretches the connected flow vertically and reads as if they belonged to it.
 * They get their own row beneath the diagram instead.
 */
function layoutSchemaGraph(graph: {
	nodes: Omit<SchemaGraphNode, "position">[];
	edges: SchemaGraphEdge[];
}): SchemaGraph {
	const connected = new Set<string>();
	for (const edge of graph.edges) {
		connected.add(edge.source);
		connected.add(edge.target);
	}
	const flowNodes = graph.nodes.filter((node) => connected.has(node.id));
	const bandNodes = graph.nodes.filter((node) => !connected.has(node.id));

	const g = new dagre.graphlib.Graph();
	g.setGraph({
		rankdir: "LR",
		ranksep: 120,
		nodesep: 32,
		marginx: MARGIN,
		marginy: MARGIN,
	});
	g.setDefaultEdgeLabel(() => ({}));

	for (const node of flowNodes) {
		g.setNode(node.id, { width: node.width, height: node.height });
	}
	for (const edge of graph.edges) {
		// Self-references do not separate ranks, so they do not participate in
		// node layout. React Flow still receives and renders the edge.
		if (edge.source === edge.target) continue;
		g.setEdge(edge.source, edge.target);
	}

	dagre.layout(g);

	const positioned = flowNodes.map((node) => {
		const laidOut = g.node(node.id);
		// dagre reports centers; React Flow positions from the top-left corner.
		return {
			...node,
			position: {
				x: (laidOut?.x ?? 0) - node.width / 2,
				y: (laidOut?.y ?? 0) - node.height / 2,
			},
		};
	});

	// Lay the unconnected band out left-to-right under the deepest flow node.
	const flowBottom = positioned.reduce(
		(max, node) => Math.max(max, node.position.y + node.height),
		MARGIN,
	);
	const bandTop = positioned.length > 0 ? flowBottom + BAND_GAP : MARGIN;
	let bandX = MARGIN;
	const banded = bandNodes.map((node) => {
		const position = { x: bandX, y: bandTop };
		bandX += node.width + 32;
		return { ...node, position };
	});

	// Preserve the caller's node order so the output does not depend on which
	// types happen to be connected.
	const byId = new Map(
		[...positioned, ...banded].map((node) => [node.id, node]),
	);
	const nodes = graph.nodes.map((node) => byId.get(node.id) ?? {
		...node,
		position: { x: MARGIN, y: MARGIN },
	});

	return { nodes, edges: graph.edges };
}

/** Build + lay out in one step. */
export function buildLaidOutSchemaGraph(opts: {
	entityTypes: EntityType[];
	relationshipTypes: RelationshipType[];
	ownerSlug: string;
	rulesBySlug: RulesBySlug;
}): SchemaGraph {
	return layoutSchemaGraph(buildSchemaGraph(opts));
}

