	return relationshipTypes.filter((relationshipType) => {
		if (relationshipType.status !== "active") return false;
		if (seen.has(relationshipType.slug)) return false;
		seen.add(relationshipType.slug);
		return true;
	});
}

/**
 * Field rows for a type's box, read from its `metadata_schema` JSON-schema
 * `properties`. `$resource` is a deliberate graph anchor with an empty schema,
 * so an empty list is expected rather than a failure.
 */
export function schemaFields(entityType: EntityType): SchemaNodeField[] {
	const schema = entityType.metadata_schema;
	if (!schema || typeof schema !== "object") return [];
	const properties = (schema as Record<string, unknown>).properties;
	if (!properties || typeof properties !== "object") return [];

	return Object.entries(properties as Record<string, unknown>).map(
		([name, spec]) => {
			const type =
				spec && typeof spec === "object"
					? (spec as Record<string, unknown>).type
					: undefined;
			return { name, type: typeof type === "string" ? type : undefined };
		},
	);
}

/**
 * Build the unpositioned graph. Only rules whose BOTH endpoints resolve to a
 * known type become edges — a rule naming a deleted type would otherwise
 * produce an edge to a node that does not exist.
 */
export function buildSchemaGraph(opts: {
	entityTypes: EntityType[];
	relationshipTypes: RelationshipType[];
	rulesBySlug: RulesBySlug;
	ownerSlug: string;
}): { nodes: Omit<SchemaGraphNode, "position">[]; edges: SchemaGraphEdge[] } {
	const { entityTypes, relationshipTypes, rulesBySlug, ownerSlug } = opts;
	const orderedEntityTypes = [...entityTypes].sort(compareSlugs);
	const resolvedRelationshipTypes =
		selectRelationshipTypesForGraph(relationshipTypes).sort(compareSlugs);

	const knownSlugs = new Set(orderedEntityTypes.map((et) => et.slug));
	const edges: SchemaGraphEdge[] = [];
	const sourceHandles = new Map<string, string[]>();
	const targetHandles = new Map<string, string[]>();
	const selfTargetHandles = new Map<string, string[]>();

	for (const rt of resolvedRelationshipTypes) {
		const rules = [...(rulesBySlug[rt.slug] ?? [])].sort((a, b) => a.id - b.id);

		for (const rule of rules) {
			const source = rule.source_entity_type_slug;
			const target = rule.target_entity_type_slug;
			if (!knownSlugs.has(source) || !knownSlugs.has(target)) continue;

			const edge = {
				// Rule id keeps sibling rules of one relationship type distinct.
				id: `rule-${rule.id}`,
				source,
				target,
				data: {
					slug: rt.slug,
					label: rt.name || rt.slug,
					isSymmetric: rt.is_symmetric,
				},
			};
			edges.push(edge);
			sourceHandles.set(source, [
				...(sourceHandles.get(source) ?? []),
				`${edge.id}-source`,
			]);
			const targetHandleMap =
				source === target ? selfTargetHandles : targetHandles;
			targetHandleMap.set(target, [
				...(targetHandleMap.get(target) ?? []),
				`${edge.id}-target`,
			]);
		}
	}

	const nodes = orderedEntityTypes.map((et) => {
		const fields = schemaFields(et);
		return {
			id: et.slug,
			width: NODE_WIDTH,
			// Header-only: the diagram is about relationships, and field lists
			// compete with the edges for attention past a handful of types.
			height: HEADER_HEIGHT,
			data: {
				slug: et.slug,
				label: et.name || et.slug,
				ownerSlug,
				icon: et.icon,
				fields,
				isSystem: isSystemEntityType(et),
				entityCount: et.entity_count,
				sourceHandleIds: sourceHandles.get(et.slug) ?? [],
				targetHandleIds: targetHandles.get(et.slug) ?? [],
				selfTargetHandleIds: selfTargetHandles.get(et.slug) ?? [],
			},
		};
	});

	return { nodes, edges };
}

const MARGIN = 24;
/** Gap between the connected flow and the unconnected band beneath it. */
const BAND_GAP = 72;

/**
 * Deterministic dagre layout — same input always yields the same arrangement,
 * so positions never need persisting and a reload does not reshuffle the map.
 *
 * Only types that a rule actually touches go through dagre. Unconnected types
 * have no edge to rank them, so dagre packs them into the first column, which
 * stretches the connected flow vertically and reads as if they belonged to it.
 * They get their own row beneath the diagram instead.
 */
function layoutSchemaGraph(graph: {
	nodes: Omit<SchemaGraphNode, "position">[];
	edges: SchemaGraphEdge[];
}): SchemaGraph {
	const connected = new Set<string>();
	for (const edge of graph.edges) {
		connected.add(edge.source);
		connected.add(edge.target);
	}
	const flowNodes = graph.nodes.filter((node) => connected.has(node.id));
	const bandNodes = graph.nodes.filter((node) => !connected.has(node.id));

	const g = new dagre.graphlib.Graph();
	g.setGraph({
		rankdir: "LR",
		ranksep: 120,
		nodesep: 32,
		marginx: MARGIN,
		marginy: MARGIN,
	});
	g.setDefaultEdgeLabel(() => ({}));

	for (const node of flowNodes) {
		g.setNode(node.id, { width: node.width, height: node.height });
	}
	for (const edge of graph.edges) {
		// Self-references do not separate ranks, so they do not participate in
		// node layout. React Flow still receives and renders the edge.
		if (edge.source === edge.target) continue;
		g.setEdge(edge.source, edge.target);
	}

	dagre.layout(g);

	const positioned = flowNodes.map((node) => {
		const laidOut = g.node(node.id);
		// dagre reports centers; React Flow positions from the top-left corner.
		return {
			...node,
			position: {
				x: (laidOut?.x ?? 0) - node.width / 2,
				y: (laidOut?.y ?? 0) - node.height / 2,
			},
		};
	});

	// Lay the unconnected band out left-to-right under the deepest flow node.
	const flowBottom = positioned.reduce(
		(max, node) => Math.max(max, node.position.y + node.height),
		MARGIN,
	);
	const bandTop = positioned.length > 0 ? flowBottom + BAND_GAP : MARGIN;
	let bandX = MARGIN;
	const banded = bandNodes.map((node) => {
		const position = { x: bandX, y: bandTop };
		bandX += node.width + 32;
		return { ...node, position };
	});

	// Preserve the caller's node order so the output does not depend on which
	// types happen to be connected.
	const byId = new Map(
		[...positioned, ...banded].map((node) => [node.id, node]),
	);
	const nodes = graph.nodes.map((node) => byId.get(node.id) ?? {
		...node,
		position: { x: MARGIN, y: MARGIN },
	});

	return { nodes, edges: graph.edges };
}

/** Build + lay out in one step. */
export function buildLaidOutSchemaGraph(opts: {
	entityTypes: EntityType[];
	relationshipTypes: RelationshipType[];
	ownerSlug: string;
	rulesBySlug: RulesBySlug;
}): SchemaGraph {
	return layoutSchemaGraph(buildSchemaGraph(opts));
}

