import { createFileRoute, redirect } from "@tanstack/react-router";

// Permissions now lives in the Guardrails Access box (UI consolidation only —
// storage and enforcement are unchanged). Keep the old route as a redirect so
// existing links don't break.
export const Route = createFileRoute("/$owner/agents/$agentId/permissions")({
	beforeLoad: ({ params }) => {
		throw redirect({
