/** Deterministic initials for an agent's avatar glyph. */
function agentInitial(name: string): string {
	return name.trim().charAt(0).toUpperCase() || "?";
}

/**
 * Per-agent sub-pages in the sidebar. Chat is the agent row itself.
 *
 * The split is by KIND, not by count: what you work with (Behaviors, Skills)
 * is a sidebar destination; what you configure once (Identity, Guardrails,
 * Permissions, and the settings proper) stays behind the single Settings row
 * and keeps its tab strip there. Promoting all seven would make every agent a
 * seven-row tree and give one-time config the same weight as daily work.
 */
