	{
		key: "behaviors",
		label: "Behaviors",
		icon: ListChecks,
		subpath: "behaviors",
	},
	{ key: "skills", label: "Skills", icon: Sparkles, subpath: "skills" },
	{
		key: "guardrails",
		label: "Guardrails",
		icon: Shield,
		subpath: "guardrails",
	},
	{ key: "settings", label: "Settings", icon: Settings, subpath: "settings" },
] as const;

/**
