/**
 * Right-aligned record count for a Context child row. Rendered even at zero —
 * an explicit 0 is the useful signal that a type exists but has nothing in it,
 * which is otherwise indistinguishable from the count still loading.
 */
function EntityCount({ count }: { count: number }) {
	return (
		<span className="shrink-0 text-[11px] tabular-nums text-sidebar-foreground/40">
			{count}
		</span>
	);
}

/**
 * Context in the roster: the row links to the entity map, the chevron expands
 * the workspace's entity types with their record counts.
 *
 * System types (`$member`, `$resource`, `$canvas`) are excluded by
 * `useVisibleEntityTypes` — they are infrastructure anchors rather than things
 * you browse, and they still appear as nodes on the map itself.
 */
function ContextGroup({
	ownerSlug,
	active,
	searchRecord,
}: {
	ownerSlug: string;
	active: boolean;
	searchRecord: Record<string, unknown>;
}) {
	const section = OWNER_SECTIONS.context;
	const { open, setOpen } = useRouteDefaultOpen(active);
	const { visible } = useVisibleEntityTypes(ownerSlug);
	// The scoped type currently being browsed, so its row takes the highlight
	// instead of the parent Context row.
	const activeTypeSlug =
		typeof searchRecord.entityType === "string"
			? searchRecord.entityType
			: undefined;

	return (
		<Collapsible open={open} onOpenChange={setOpen}>
			<div
				className={cn(
					"mx-2 flex items-center gap-2 rounded-md py-1.5 pl-3 pr-2 text-sm transition-colors",
					active && !(open && activeTypeSlug)
						? "bg-sidebar-accent text-sidebar-accent-foreground"
						: "text-sidebar-foreground/80 hover:bg-sidebar-accent/60 hover:text-sidebar-foreground",
				)}
			>
				<Link
					to={section.to}
					params={{ owner: ownerSlug }}
					search={section.search as never}
					className="flex min-w-0 flex-1 items-center gap-2"
				>
					<section.icon className="h-3.5 w-3.5 shrink-0 text-sidebar-foreground/60" />
					<span className="min-w-0 flex-1 truncate">{section.label}</span>
				</Link>
				{/* No types yet ⇒ nothing to expand, so the chevron would be a
				    control that does nothing. The row still links to the map. */}
				{visible.length > 0 ? (
					<CollapsibleTrigger asChild>
						<button
							type="button"
							aria-label={
								open ? "Collapse entity types" : "Expand entity types"
							}
							title={open ? "Collapse entity types" : "Expand entity types"}
							className="shrink-0"
						>
							<GroupChevron open={open} />
						</button>
					</CollapsibleTrigger>
				) : null}
			</div>
			<CollapsibleContent>
				{visible.map((entityType) => {
					const link = memoryBrowseTypeSearch(ownerSlug, entityType.slug, {
						view: "entities",
					});
					return (
						<NavRow
							key={entityType.slug}
							to={link.to}
							params={link.params}
							search={link.search}
							active={activeTypeSlug === entityType.slug}
							label={entityType.name || entityType.slug}
							indent
							trailing={<EntityCount count={entityType.entity_count ?? 0} />}
						/>
					);
				})}
			</CollapsibleContent>
		</Collapsible>
	);
}

