		// Context carries the workspace's entity types as children,
		// so it is a collapsible group rather than a plain row.
		if (key === "context") {
			return (
				<ContextGroup
					key={key}
					ownerSlug={owner}
					active={active}
					searchRecord={searchRecord}
				/>
			);
		}
		return (
			<NavRow
				key={key}
				to={section.to}
				params={{ owner }}
				search={section.search}
				active={active}
				icon={section.icon}
				label={section.label}
			/>
		);
	})}

