import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import {
	createMemoryHistory,
	createRootRoute,
	createRoute,
	createRouter,
	RouterProvider,
} from "@tanstack/react-router";
import { render, screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import { AppSidebar } from "./app-sidebar";

// The sidebar is pure nav over hook-provided data — pin the data so the test
// exercises only the site-map structure (expansion + link targets).
vi.mock("@/hooks/use-working-agents", () => ({
	useWorkingAgents: () => ({
		rosterAgents: [
			{ agentId: "agent-a", name: "Alpha", status: "idle" as const },
			{ agentId: "agent-b", name: "Beta", status: "idle" as const },
		],
		workingAgents: [],
		systemAgentId: null,
		isLoading: false,
	}),
}));

vi.mock("@/hooks/use-org-context", () => ({
	useOrgContext: () => ({ currentOwner: "test-org" }),
}));

vi.mock("@/lib/auth-state", () => ({
	useAuthState: () => ({ session: null }),
}));

vi.mock("@/components/sidebar/organization-dropdown", () => ({
	OrganizationDropdown: () => <div data-testid="org-dropdown" />,
}));

/**
 * Minimal route tree covering every path the sidebar links to, with the
 * sidebar mounted at the root so `useLocation` / `useParams` see the real
 * route context.
 */
async function renderSidebarAt(path: string) {
	const rootRoute = createRootRoute({ component: () => <AppSidebar /> });
	const ownerRoute = createRoute({
		getParentRoute: () => rootRoute,
		path: "/$owner",
	});
	const agentRoute = createRoute({
		getParentRoute: () => ownerRoute,
		path: "agents/$agentId",
	});
	const memoryRoute = createRoute({
		getParentRoute: () => ownerRoute,
		path: "memory",
		validateSearch: (s: Record<string, unknown>) => s,
	});
	const routeTree = rootRoute.addChildren([
		ownerRoute.addChildren([
			createRoute({ getParentRoute: () => ownerRoute, path: "/" }),
			memoryRoute,
			createRoute({ getParentRoute: () => ownerRoute, path: "connectors" }),
			agentRoute.addChildren([
				createRoute({ getParentRoute: () => agentRoute, path: "chat" }),
				createRoute({ getParentRoute: () => agentRoute, path: "behaviors" }),
				createRoute({ getParentRoute: () => agentRoute, path: "skills" }),
				createRoute({ getParentRoute: () => agentRoute, path: "guardrails" }),
				createRoute({ getParentRoute: () => agentRoute, path: "settings" }),
			]),
		]),
	]);
	const router = createRouter({
		routeTree,
		history: createMemoryHistory({ initialEntries: [path] }),
	});
	const queryClient = new QueryClient({
		defaultOptions: { queries: { retry: false } },
	});
	render(
		<QueryClientProvider client={queryClient}>
			{/* biome-ignore lint/suspicious/noExplicitAny: synthetic test router */}
			<RouterProvider router={router as any} />
		</QueryClientProvider>,
	);
	// Both agent rows mounting proves the router matched and the tree settled.
	await screen.findByText("Alpha");
	await screen.findByText("Beta");
}

describe("AppSidebar site map", () => {
	it("expands only the route-active agent to its configuration rows (no Chat child)", async () => {
		await renderSidebarAt("/test-org/agents/agent-a/chat");

		expect(screen.queryByRole("link", { name: "Chat" })).toBeNull();
		const behaviors = screen.getByRole("link", { name: "Behaviors" });
		const skills = screen.getByRole("link", { name: "Skills" });
		const guardrails = screen.getByRole("link", { name: "Guardrails" });
		const settings = screen.getByRole("link", { name: "Settings" });
		expect(behaviors).toHaveAttribute(
			"href",
			"/test-org/agents/agent-a/behaviors",
		);
		expect(skills).toHaveAttribute("href", "/test-org/agents/agent-a/skills");
		expect(guardrails).toHaveAttribute(
			"href",
			"/test-org/agents/agent-a/guardrails",
		);
		expect(settings).toHaveAttribute(
			"href",
			"/test-org/agents/agent-a/settings",
		);
		expect(screen.getByRole("link", { name: /Alpha/ })).toHaveAttribute(
			"href",
			"/test-org/agents/agent-a/chat",
		);
	});

	it("renders no agent children when no agent route is active", async () => {
		await renderSidebarAt("/test-org/memory");

		expect(screen.queryByRole("link", { name: "Behaviors" })).toBeNull();
		expect(screen.queryByRole("link", { name: "New chat" })).toBeNull();
	});

	it("links Connect straight to /connectors", async () => {
		await renderSidebarAt("/test-org/connectors");

		expect(screen.getByRole("link", { name: "Connect" })).toHaveAttribute(
			"href",
			"/test-org/connectors",
		);
	});

	// Activity = Memory Events; Context = the entity schema. Not a /activity page.
	it("links Activity to /memory and Context to /memory?view=entities", async () => {
		await renderSidebarAt("/test-org/memory");

		expect(screen.getByRole("link", { name: "Activity" })).toHaveAttribute(
			"href",
			"/test-org/memory",
		);
		expect(screen.getByRole("link", { name: "Context" })).toHaveAttribute(
			"href",
			"/test-org/memory?view=entities",
		);
		// This row was "Models" (collided with model *providers* under Connect),
		// then "Entities". Neither old label may survive anywhere in the nav.
		expect(screen.queryByRole("link", { name: "Models" })).toBeNull();
		expect(screen.queryByRole("link", { name: "Entities" })).toBeNull();
	});
});

