import { createFileRoute, redirect } from "@tanstack/react-router";
import { INFERENCE_ROW_KEY_PREFIX } from "@/lib/connectors/inference-rows";

// Redirect-only: chat messages sent since PR #1847 contain
// /$owner/infrastructure/models links immutably, so this route exists solely to
// keep them resolving ("infrastructure" stays in OWNER_ROUTE_SEGMENTS for the
// same reason). ?provider targets the provider's connector detail page; ?model
// rides along to open its edit controls.
export const Route = createFileRoute("/$owner/infrastructure/models")({
	validateSearch: (search: Record<string, unknown>) => ({
		provider: typeof search.provider === "string" ? search.provider : undefined,
		model: typeof search.model === "string" ? search.model : undefined,
	}),
	beforeLoad: ({ params, search }) => {
		if (!search.provider) {
			throw redirect({
				to: "/$owner/connectors",
				params: { owner: params.owner },
			});
		}
		throw redirect({
			to: "/$owner/connectors/$connectorKey",
			params: {
				owner: params.owner,
				connectorKey: `${INFERENCE_ROW_KEY_PREFIX}${search.provider}`,
			},
			search: { model: search.model },
		});
	},
});

