		);
	});

	it("renders no agent children when no agent route is active", async () => {
		await renderSidebarAt("/test-org/memory");

		expect(screen.queryByRole("link", { name: "Behaviors" })).toBeNull();
		expect(screen.queryByRole("link", { name: "New chat" })).toBeNull();
	});

	it("links Connect straight to /connectors", async () => {
		await renderSidebarAt("/test-org/connectors");

		expect(screen.getByRole("link", { name: "Connect" })).toHaveAttribute(
			"href",
			"/test-org/connectors",
		);
	});

	// Activity = Memory Events; Context = the entity schema. Not a /activity page.
	it("links Activity to /memory and Context to /memory?view=entities", async () => {
		await renderSidebarAt("/test-org/memory");

		expect(screen.getByRole("link", { name: "Activity" })).toHaveAttribute(
			"href",
			"/test-org/memory",
		);
		expect(screen.getByRole("link", { name: "Context" })).toHaveAttribute(
			"href",
			"/test-org/memory?view=entities",
		);
		// This row was "Models" (collided with model *providers* under Connect),
		// then "Entities". Neither old label may survive anywhere in the nav.
		expect(screen.queryByRole("link", { name: "Models" })).toBeNull();
		expect(screen.queryByRole("link", { name: "Entities" })).toBeNull();
	});

	it("expands Context to the entity types, each with its record count", async () => {
		await renderSidebarAt("/test-org/memory?view=entities");

		const company = await screen.findByRole("link", { name: /Company/ });
		// `type` is the scope key memoryScopeSearch writes — an entityType-style
		// key would link somewhere the Entities view does not scope on.
		expect(company).toHaveAttribute("href", "/test-org/memory?type=company");
		expect(company).toHaveTextContent("12");

		// Zero renders rather than being hidden: an explicit 0 distinguishes an
		// empty type from a count that has not loaded.
		expect(await screen.findByRole("link", { name: /Goal/ })).toHaveTextContent(
			"0",
		);
	});

	it("collapses Context when the entities view is not active", async () => {
		await renderSidebarAt("/test-org/connectors");

		expect(screen.queryByRole("link", { name: /Company/ })).toBeNull();
	});

	// The scoped type takes the highlight off the parent Context row. Reading
	// `entityType` instead of `type` here silently highlights nothing, and an
	// href-only assertion cannot catch that — the links are correct either way.
	it("highlights the scoped type's row, not the Context row", async () => {
		await renderSidebarAt("/test-org/memory?view=entities&type=company");

		const company = await screen.findByRole("link", { name: /Company/ });
		const goal = await screen.findByRole("link", { name: /Goal/ });
		// Match the class list, not a substring: every inactive row carries
		// `hover:bg-sidebar-accent/60`, which a `toContain` would match too.
		expect(company).toHaveClass("bg-sidebar-accent");
		expect(goal).not.toHaveClass("bg-sidebar-accent");
	});

	it("keeps the type highlighted while browsing one of its records", async () => {
		await renderSidebarAt("/test-org/memory?entity=company/acme");

		expect(await screen.findByRole("link", { name: /Company/ })).toHaveClass(
			"bg-sidebar-accent",
		);
	});
});

