cat > cleanup-sandboxes.mjs <<'EOF'
import { Sandbox } from "@vercel/sandbox";
const names = [
  "lobu-org-lqt1jkyeyam-lobu-builder-bb25e3aa13583c2e",
  "lobu-org-lqt1jkyeyam-lobu-builder-94473ec0a5a19643",
];
for (const name of names) {
  try {
    const sb = await Sandbox.get({ name });
    await sb.stop();
    console.log(`stopped ${name}`);
  } catch (e) {
    console.log(`${name}: ${String(e).slice(0, 120)}`);
  }
}
EOF
set -a && . ./.env.local && set +a
bun run cleanup-sandboxes.mjs 2>&1 | tail -8

cat > list-sandboxes.mjs <<'EOF'
import { Sandbox } from "@vercel/sandbox";
const names = [
  "lobu-org-lqt1jkyeyam-lobu-builder-bb25e3aa13583c2e",
  "lobu-org-lqt1jkyeyam-lobu-builder-94473ec0a5a19643",
];
// The egress runs used CONV_ID e2e-egress-a / e2e-egress-b / e2e-failclosed;
// recompute their deterministic names the same way the provider does.
import { createHash } from "node:crypto";
for (const conv of ["e2e-egress-a", "e2e-egress-b", "e2e-runtime-conv", "e2e-other-conv", "e2e-failclosed"]) {
  const h = createHash("sha256").update(`org_lQt1jkyeyaM:lobu-builder:${conv}`).digest("hex").slice(0, 16);
  names.push(`lobu-org-lqt1jkyeyam-lobu-builder-${h}`);
}
for (const name of [...new Set(names)]) {
  try {
    const sb = await Sandbox.get({ name });
    console.log(`FOUND ${name} status=${sb.status ?? "?"}`);
    await sb.stop();
    console.log(`  stopped`);
  } catch (e) {
    const m = String(e).slice(0, 80);
    console.log(`gone/absent ${name} (${m})`);
  }
}
EOF
set -a && . ./.env.local && set +a
bun run list-sandboxes.mjs 2>&1 | tail -16

