/**
 * `GET /sandboxes` → `providerCatalog` shape contract.
 *
 * The catalog exists so the create form can render a provider's credential
 * fields without hardcoding them. It is display metadata only: it must never
 * carry a credential VALUE, and it must not echo `systemEnvVar` — that names a
 * deployment-wide env var and is operator detail, not something the browser
 * needs in order to draw a form.
 *
 * Drives the REAL mounted route rather than a copy of its projection: a test
 * that re-implements the mapping still passes when the route starts spreading
 * the raw registry field, which is exactly the leak being guarded against.
 * The sandbox store is stubbed so this stays a unit test (no DB); the runtime
 * registry is the real one, so a new provider or field is covered for free.
 */
import { beforeEach, describe, expect, mock, test } from "bun:test";
import { authStash, installRouteTestMocks } from "./helpers/route-test-mocks";

installRouteTestMocks();

// The catalog is built from the registry alone, but GET / also lists rows.
// Stub the store so the route runs without a database.
mock.module("../stores/sandbox-store", () => ({
	listSandboxes: async () => [],
	createSandbox: async () => undefined,
	deleteSandbox: async () => undefined,
	setSandboxCredentialName: async () => undefined,
}));
// Spread the real module: other route modules pull further exports from it,
// and a narrow stub breaks their imports rather than this test's.
const realProviderSecrets = await import("../stores/provider-secrets.js");
mock.module("../stores/provider-secrets", () => ({
	...realProviderSecrets,
	readSandboxSecret: async () => null,
	writeSandboxSecret: async () => undefined,
}));

const { sandboxRoutes } = await import("../sandbox-routes.js");
const { listGatewayRuntimeProviderIds } = await import(
	"../../gateway/runtime/index.js"
);

const ALLOWED_FIELD_KEYS = ["key", "label", "required", "secret"].sort();

interface CatalogEntry {
	id: string;
	credentialFields: Record<string, unknown>[];
}

async function fetchProviderCatalog(): Promise<CatalogEntry[]> {
	const res = await sandboxRoutes.request("/", { method: "GET" });
	expect(res.status).toBe(200);
	const body = (await res.json()) as { providerCatalog?: CatalogEntry[] };
	expect(Array.isArray(body.providerCatalog)).toBe(true);
	return body.providerCatalog ?? [];
}

describe("GET /sandboxes providerCatalog contract", () => {
	beforeEach(() => {
		authStash.organizationId = "org-sandbox-catalog";
		authStash.authSource = "session";
	});

	test("exposes every registered runtime provider", async () => {
		const catalog = await fetchProviderCatalog();
		expect(catalog.map((e) => e.id).sort()).toEqual(
			listGatewayRuntimeProviderIds().sort(),
		);
		expect(catalog.length).toBeGreaterThan(0);
	});

	test("emits only display metadata — never systemEnvVar or a credential value", async () => {
		const catalog = await fetchProviderCatalog();
		// Guard the guard: a catalog with no fields would pass vacuously.
		expect(catalog.some((e) => e.credentialFields.length > 0)).toBe(true);

		for (const entry of catalog) {
			for (const field of entry.credentialFields) {
				expect(Object.keys(field).sort()).toEqual(ALLOWED_FIELD_KEYS);
				expect(field).not.toHaveProperty("systemEnvVar");
				expect(field).not.toHaveProperty("value");
			}
		}
	});

	test("keeps the secret flag, so the form still masks token inputs", async () => {
		const catalog = await fetchProviderCatalog();
		const vercel = catalog.find((e) => e.id === "vercel");
		expect(vercel).toBeTruthy();
		const token = vercel?.credentialFields.find((f) => f.key === "token");
		expect(token?.secret).toBe(true);
	});
});

import { createFileRoute, redirect } from "@tanstack/react-router";
import { MemoryConnectorGroupsProvider } from "@/components/memory/memory-connector-groups";
import { MemoryHomePane } from "@/components/memory/memory-home-pane";
import { OwnerWorkspaceGate } from "@/components/owner-workspace-gate";
import { useWorkspaceRoot } from "@/lib/api";
import {
	memorySearchNeedsCanonicalRedirect,
	parseAgentScope,
	parseEntityScope,
	parseScheduleScope,
	parseWatcherScope,
	resolveMemoryView,
} from "@/lib/memory-browse";
import { pruneSearch } from "@/lib/router-search";
import { decodeEntityTypeParam } from "@/lib/url";

export const Route = createFileRoute("/$owner/memory/")({
	loader: ({ context: { queryClient }, params }) => {
		void queryClient.prefetchQuery(
			useWorkspaceRoot.queryOptions(params.owner, { slug: params.owner }),
		);
	},
	// Migrate legacy browsing to the current model: a `?browse_path` (an entity
	// detail) becomes the `/memory/<type>/<slug>` path; a bare `?browse_type`
	// becomes the in-place `?type=<slug>` scope. Temporary — drop after a release.
	beforeLoad: ({ params, search }) => {
		const s = search as Record<string, unknown>;
		const legacyDetail =
			typeof s.browse_path === "string" && s.browse_path.trim()
				? s.browse_path.trim()
				: undefined;
		if (legacyDetail) {
			throw redirect({
				to: "/$owner/memory/$",
				params: { owner: params.owner, _splat: legacyDetail },
				search: {},
				replace: true,
			});
		}
		const legacyType =
			typeof s.browse_type === "string" && s.browse_type.trim()
				? s.browse_type.trim()
				: undefined;
		if (legacyType) {
			throw redirect({
				to: "/$owner/memory",
				params: { owner: params.owner },
				search: pruneSearch({
					type: decodeEntityTypeParam(legacyType),
					view: s.browse_view === "events" ? "events" : undefined,
					create: s.create === true || s.create === "true" ? true : undefined,
				}) as Record<string, string | undefined>,
				replace: true,
			});
		}
		// Memory Feeds tab removed — old ?view=feeds deep links land on Events.
		if (s.view === "feeds") {
			throw redirect({
				to: "/$owner/memory",
				params: { owner: params.owner },
				search: pruneSearch({
					...s,
					view: "events",
				}) as Record<string, string | undefined>,
				replace: true,
			});
		}
		const canonical = memorySearchNeedsCanonicalRedirect(s);
		if (canonical) {
			throw redirect({
				to: "/$owner/memory",
				params: { owner: params.owner },
				search: canonical,
				replace: true,
			});
		}
	},
	component: MemoryPage,
	validateSearch: (search: Record<string, unknown>) => {
		const result = pruneSearch(search) as Record<string, string | undefined>;
		// `stringifyRouterSearch` JSON-parses primitive search values, so `?create=true`
		// round-trips as boolean `true` — normalize back to the string the UI reads.
		if (search.create === true || search.create === "true") {
			result.create = "true";
		}
		// Create-entity-type subpage under the Context destination.
		if (search.create_type === true || search.create_type === "true") {
			result.create_type = "true";
		}
		return result;
	},
});

function MemoryPage() {
	const { owner } = Route.useParams();
	const search = Route.useSearch();
	const typeScope =
		typeof search.type === "string" && search.type.trim()
			? decodeEntityTypeParam(search.type.trim())
			: undefined;
	const entityScope = parseEntityScope(search);
	const agentScope = parseAgentScope(search);
	const watcherScope = parseWatcherScope(search);
	const scheduleScope = parseScheduleScope(search);
	const createType = search.create_type === "true";
	// Creating a type is always an Entities subpage.
	const view = createType
		? "entities"
		: resolveMemoryView(
				search.view,
				typeScope != null || entityScope != null,
			);
	const create = search.create === "true";

	return (
		<div className="flex flex-1 flex-col gap-6 px-4 py-6 lg:px-6">
			<OwnerWorkspaceGate owner={owner}>
				{(props) => (
					<MemoryConnectorGroupsProvider
						organizationId={props.organizationId}
						isWorkspaceLoading={props.isWorkspaceLoading}
					>
						<div className="flex min-h-0 min-w-0 flex-1 flex-col">
							<MemoryHomePane
								organizationId={props.organizationId}
								ownerSlug={props.ownerSlug}
								typeScope={typeScope}
								entityScope={entityScope}
								agentScope={agentScope}
								watcherScope={watcherScope}
								scheduleScope={scheduleScope}
								view={view}
								create={create}
								createType={createType}
							/>
						</div>
					</MemoryConnectorGroupsProvider>
				)}
			</OwnerWorkspaceGate>
		</div>
	);
}

import { Link, useNavigate } from "@tanstack/react-router";
import { Boxes, ChevronRight, X } from "lucide-react";
import type { ReactNode } from "react";
import { EntityTypeGraphView } from "@/components/entities/entity-type-graph-view";
