/**
 * E2E: does a connector-contributed `gh` actually run through the agent's bash?
 *
 * Drives the REAL createEmbeddedBashOps with the REAL /opt/homebrew/bin/gh and a
 * REAL macOS sandbox-exec strategy — no fixture binaries, no unsandboxed opt-in.
 * That combination is what production does and what no existing test covers.
 */
import { createEmbeddedBashOps } from "../../../../../Users/burakemre/Code/lobu/.claude/worktrees/sidebar-nav/packages/agent-worker/src/embedded/just-bash-bootstrap";
import { probeSandboxStrategy } from "../../../../../Users/burakemre/Code/lobu/.claude/worktrees/sidebar-nav/packages/agent-worker/src/embedded/exec-sandbox";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

const workspace = fs.mkdtempSync(path.join(os.tmpdir(), "gh-e2e-"));

async function run(label: string, nixPackages: string | undefined, cmd: string) {
  if (nixPackages === undefined) delete process.env.NIX_PACKAGES;
  else process.env.NIX_PACKAGES = nixPackages;

  const ops = await createEmbeddedBashOps({ workspaceDir: workspace });
  const res: any = await ops.exec({ command: cmd, timeout_ms: 20000 });
  const out = ((res.stdout ?? "") + (res.stderr ?? "")).trim().split("\n")[0];
  console.log(
    `[${label}] NIX_PACKAGES=${nixPackages ?? "(unset)"} :: ${cmd}\n` +
      `    exit=${res.exit_code ?? res.exitCode} out=${out.slice(0, 120)}`
  );
  return res;
}

console.log("sandbox strategy:", JSON.stringify(probeSandboxStrategy()));
console.log("workspace:", workspace);

// 1. DECLARED gh — the headline claim. Should run (exit 0), not 127.
await run("declared-gh", "gh", "gh --version");
// 2. DECLARED git — contributed alongside gh in the same declaration.
await run("declared-git", "git", "git --version");
// 3. UNDECLARED gh — declaration is what widens discovery, so this must 127.
await run("undeclared-gh", undefined, "gh --version");
// 4. UNDECLARED-but-on-PATH curl — the guard against widening to all of PATH.
await run("undeclared-curl", "gh", "curl --version");
// 5. Interpreter stays blocked even when declared (UNSANDBOXED_INTERPRETERS).
await run("declared-node", "nodejs", "node --version");

fs.rmSync(workspace, { recursive: true, force: true });

