const sandboxStrategy = probeSandboxStrategy();

// Registration is gated on ISOLATION, which has two independent sources:
// a real per-exec sandbox, or a deployment that hosts a single tenant.
//
// The container hosts every worker and the gateway as the same user, so a
// shell-capable CLI (gh runs extensions and aliases) can read sibling
// `workspaces/{agentId}` directories and /proc/1/environ — reproduced: a
// registered tool read another tenant's workspace file. What makes that a
// breach is the SIBLING, not the missing sandbox. A single-tenant deployment
// has no sibling to leak to, so the sandbox is not load-bearing there.
//
// Gating on the probe alone got this wrong in both directions: it denied
// single-tenant deployments a working CLI for no security benefit, and it
// would have permitted registration on any multi-tenant host where bwrap
// happened to start. Tenancy is a property of the deployment and cannot be
// inferred from a syscall, so it is declared.
//
// Defaults to multi-tenant: an operator who has not thought about it gets
// the safe answer.
const isolation = resolveWorkerIsolation();
const registerSpawnedBinaries = isolation.isolated;

