cat >> packages/agent-worker/src/__tests__/embedded-just-bash-bootstrap.test.ts <<'EOF'

/**
 * Registration is gated on ISOLATION, not on the sandbox probe alone.
 *
 * The probe was an accidental proxy for the real question ("can this worker
 * reach another tenant's data?") and got it wrong in both directions: it
 * denied single-tenant deployments a CLI for no benefit, and would have
 * permitted registration on any multi-tenant host where bwrap happened to
 * start. These pin the declared-tenancy contract instead.
 */
describe("worker isolation gate", () => {
  test("defaults to NOT isolated when nothing is declared", () => {
    process.env.LOBU_EXEC_SANDBOX = "off";
    delete process.env.LOBU_DEPLOYMENT_TENANCY;
    delete process.env.LOBU_ALLOW_UNSANDBOXED_EXEC;
    resetSandboxProbeForTests();

    const isolation = resolveWorkerIsolation();
    expect(isolation.isolated).toBe(false);
    expect(isolation.reason).toBe("none");
  });

  test("SECURITY: multi-tenant declaration does NOT isolate", () => {
    // The failure that matters. An operator who names their real topology must
    // not thereby unlock CLIs — only `single` does.
    process.env.LOBU_EXEC_SANDBOX = "off";
    process.env.LOBU_DEPLOYMENT_TENANCY = "multi";
    delete process.env.LOBU_ALLOW_UNSANDBOXED_EXEC;
    resetSandboxProbeForTests();

    expect(resolveWorkerIsolation().isolated).toBe(false);
  });

  test("single-tenant declaration isolates without a sandbox", () => {
    process.env.LOBU_EXEC_SANDBOX = "off";
    process.env.LOBU_DEPLOYMENT_TENANCY = "single";
    delete process.env.LOBU_ALLOW_UNSANDBOXED_EXEC;
    resetSandboxProbeForTests();

    const isolation = resolveWorkerIsolation();
    expect(isolation.isolated).toBe(true);
    expect(isolation.reason).toBe("single-tenant");
  });

  test("a real sandbox isolates regardless of declared tenancy", () => {
    if (!realSandboxAvailable) return;
    delete process.env.LOBU_EXEC_SANDBOX;
    process.env.LOBU_DEPLOYMENT_TENANCY = "multi";
    delete process.env.LOBU_ALLOW_UNSANDBOXED_EXEC;
    resetSandboxProbeForTests();

    const isolation = resolveWorkerIsolation();
    expect(isolation.isolated).toBe(true);
    expect(isolation.reason).toBe("sandbox");
  });

  test("the unsandboxed opt-in still works, and is reported as such", () => {
    process.env.LOBU_EXEC_SANDBOX = "off";
    delete process.env.LOBU_DEPLOYMENT_TENANCY;
    process.env.LOBU_ALLOW_UNSANDBOXED_EXEC = "1";
    resetSandboxProbeForTests();

    const isolation = resolveWorkerIsolation();
    expect(isolation.isolated).toBe(true);
    expect(isolation.reason).toBe("unsandboxed-opt-in");
  });

  test("a declared CLI registers under single-tenant, with no sandbox", async () => {
    // End to end through the real bootstrap: the gate is what changed, so prove
    // the CLI actually becomes reachable rather than only that a flag flipped.
    const workspace = fs.realpathSync(
      fs.mkdtempSync(path.join(os.tmpdir(), "lobu-tenancy-"))
    );
    tempDirs.push(workspace);
    const usrBin = path.join(workspace, "usr", "bin");
    fs.mkdirSync(usrBin, { recursive: true });
    const fakeGh = path.join(usrBin, "gh");
    fs.writeFileSync(fakeGh, '#!/bin/sh\necho "gh version 2.23.0"\n', "utf8");
    fs.chmodSync(fakeGh, 0o755);

    process.env.PATH = `${usrBin}:${process.env.PATH ?? ""}`;
    process.env.LOBU_EXEC_SANDBOX = "off";
    process.env.LOBU_DEPLOYMENT_TENANCY = "single";
    delete process.env.LOBU_ALLOW_UNSANDBOXED_EXEC;
    process.env.NIX_PACKAGES = "gh";
    delete process.env.LOBU_WORKSPACE_BACKEND;
    resetSandboxProbeForTests();

    const ops = await createEmbeddedBashOps({ workspaceDir: workspace });
    const chunks: string[] = [];
    const result = await ops.exec("gh --version", "/", {
      onData: (chunk) => chunks.push(chunk.toString()),
      timeout: 5,
    });

    expect(result.exitCode).toBe(0);
    expect(chunks.join("")).toContain("gh version");
  });

  test("SECURITY: the same CLI stays unreachable when tenancy is undeclared", async () => {
    const workspace = fs.realpathSync(
      fs.mkdtempSync(path.join(os.tmpdir(), "lobu-tenancy-deny-"))
    );
    tempDirs.push(workspace);
    const usrBin = path.join(workspace, "usr", "bin");
    fs.mkdirSync(usrBin, { recursive: true });
    const fakeGh = path.join(usrBin, "gh");
    fs.writeFileSync(fakeGh, '#!/bin/sh\necho "gh version 2.23.0"\n', "utf8");
    fs.chmodSync(fakeGh, 0o755);

    process.env.PATH = `${usrBin}:${process.env.PATH ?? ""}`;
    process.env.LOBU_EXEC_SANDBOX = "off";
    delete process.env.LOBU_DEPLOYMENT_TENANCY;
    delete process.env.LOBU_ALLOW_UNSANDBOXED_EXEC;
    process.env.NIX_PACKAGES = "gh";
    delete process.env.LOBU_WORKSPACE_BACKEND;
    resetSandboxProbeForTests();

    const ops = await createEmbeddedBashOps({ workspaceDir: workspace });
    const chunks: string[] = [];
    const result = await ops.exec("gh --version", "/", {
      onData: (chunk) => chunks.push(chunk.toString()),
      timeout: 5,
    });

    expect(result.exitCode).not.toBe(0);
    expect(chunks.join("")).not.toContain("gh version 2.23.0");
  });
});
