1	/**
2	 * Worker-side just-bash bootstrap for embedded deployment mode.
3	 *
4	 * Creates a just-bash Bash instance from environment variables and wraps it
5	 * as a BashOperations interface for pi-coding-agent's bash tool.
6	 *
7	 * When nix binaries are detected on PATH (via nix-shell wrapper from gateway)
8	 * or known CLI tools (e.g. lobu) are found, they are registered as
9	 * just-bash customCommands that delegate to real exec.
10	 */
11	
12	import { execFile } from "node:child_process";
13	import fs from "node:fs";
14	import path from "node:path";
15	import { stripEnv } from "@lobu/core";
16	import type { BashOperations } from "@mariozechner/pi-coding-agent";
17	import { SENSITIVE_WORKER_ENV_KEYS } from "../shared/worker-env-keys";
18	import type { GatewayParams } from "@lobu/plugin-toolkit";
19	import { buildEgressFetch } from "./egress-fetch";
20	import {
21	  type SandboxStrategy,
22	  probeSandboxStrategy,
23	  wrapInvocation,
24	} from "./exec-sandbox";
25	import type { McpCliCommand, McpRuntimeRef } from "./mcp-cli-commands";
26	import { buildMcpCliCommands } from "./mcp-cli-commands";
27	import { getWorkerRuntimeProvider } from "./runtime";
28	
29	const EMBEDDED_BASH_LIMITS = {
30	  maxCommandCount: 50_000,
31	  maxLoopIterations: 50_000,
32	  maxCallDepth: 50,
33	} as const;
34	
35	interface SandboxContext {
36	  strategy: SandboxStrategy;
37	  workspaceDir: string;
38	  /** Whether the spawned binary may open sockets. just-bash's domain allowlist
39	   * still gates the interpreter; this controls the OS network namespace. */
40	  allowNet?: boolean;
41	  /** Per-invocation cwd inside bwrap's /workspace namespace. */
42	  bwrapCwd?: string;
43	}
44	
45	export function buildBinaryInvocation(
46	  binaryPath: string,
47	  args: string[],
48	  sandbox?: SandboxContext
49	): { command: string; args: string[] } {
50	  let inner: { command: string; args: string[] } = {
51	    command: binaryPath,
52	    args,
53	  };
54	  try {
55	    const firstLine =
56	      fs.readFileSync(binaryPath, "utf8").split("\n", 1)[0] || "";
57	    if (firstLine === "#!/usr/bin/env node" || firstLine.endsWith("/node")) {
58	      inner = { command: "node", args: [binaryPath, ...args] };
59	    }
60	  } catch {
61	    // Fall back to executing the binary directly.
62	  }
63	
64	  if (!sandbox) return inner;
65	  return wrapInvocation(sandbox.strategy, inner, {
66	    workspaceDir: sandbox.workspaceDir,
67	    allowNet: sandbox.allowNet ?? true,
68	    bwrapCwd: sandbox.bwrapCwd,
69	  });
70	}
71	
72	/**
73	 * Why a spawned binary may be registered at all.
74	 *
75	 * `sandbox`  — a real per-exec sandbox (bwrap / sandbox-exec) confines it.
76	 * `single-tenant` — the deployment declares it hosts one tenant, so there is
77	 *   no sibling workspace to read. The operator asserts this; it is never
78	 *   inferred, because nothing observable from inside the container
79	 *   distinguishes "one tenant" from "one tenant so far".
80	 * `unsandboxed-opt-in` — the pre-existing escape hatch for trusted agents.
81	 */
82	export interface WorkerIsolation {
83	  isolated: boolean;
84	  reason: "sandbox" | "single-tenant" | "unsandboxed-opt-in" | "none";
85	}
86	
87	/**
88	 * Resolve whether this worker is isolated enough to run spawned binaries.
89	 *
90	 * Order matters only for reporting — any one source is sufficient. The default
91	 * is NOT isolated: a deployment that declares nothing is treated as
92	 * multi-tenant, so the unsafe case is the one an operator has to opt into
93	 * rather than the one they get by forgetting.
94	 */
95	export function resolveWorkerIsolation(): WorkerIsolation {
96	  if (probeSandboxStrategy().kind !== "none") {
97	    return { isolated: true, reason: "sandbox" };
98	  }
99	  // Deployment-level assertion. Named for what it claims about the DEPLOYMENT,
100	  // not for what it unlocks, so it cannot read as a feature flag.
101	  const tenancy = (process.env.LOBU_WORKER_SHARES_NO_TENANTS || "").toLowerCase();
102	  if (tenancy === "single") {
103	    return { isolated: true, reason: "single-tenant" };
104	  }
105	  if (
106	    process.env.LOBU_ALLOW_UNSANDBOXED_EXEC === "1" ||
107	    process.env.LOBU_ALLOW_UNSANDBOXED_EXEC === "true"
108	  ) {
109	    return { isolated: true, reason: "unsandboxed-opt-in" };
110	  }
111	  return { isolated: false, reason: "none" };
112	}
113	
114	/**
115	 * Binaries that are full code-execution capabilities. If they land on the
116	 * just-bash allowlist, the depth/loop caps are moot — the agent can run
117	 * arbitrary code through them. They are excluded by default; an agent that
118	 * genuinely needs them must opt in via
119	 * `LOBU_ALLOW_UNSANDBOXED_EXEC=1` (set per-agent in lobu.config.ts).
120	 */
121	const UNSANDBOXED_INTERPRETERS = new Set<string>([
122	  "node",
123	  "nodejs",
124	  "bun",
125	  "deno",
126	  "python",
127	  "python3",
128	  "ruby",
129	  "perl",
130	  "lua",
131	  "bash",
132	  "sh",
133	  "zsh",
134	  "fish",
135	  "ash",
136	  "dash",
137	  "ksh",
138	  "tcsh",
139	  "csh",
140	  "curl",
141	  "wget",
142	  "git",
143	  "ssh",
144	  "scp",
145	  "rsync",
146	  "nc",
147	  "ncat",
148	  "socat",
149	  "telnet",
150	  "nix",
151	  "nix-build",
152	  "nix-shell",
153	  "nix-env",
154	  "npm",
155	  "npx",
156	  "pnpm",
157	  "yarn",
158	  "pip",
159	  "pip3",
160	  "pipx",
161	  "uv",
162	  "poetry",
163	  "gem",
164	  "cargo",
165	  "go",
166	]);
167	
168	/**
169	 * Executables installed by a declared nix package, for the packages whose CLI
170	 * is baked into the runtime image (docker/app/Dockerfile) instead of being
171	 * provisioned under /nix/store.
172	 *
173	 * A package attribute does NOT name its commands (`ripgrep` installs `rg`), so
174	 * this listing is explicit. Inferring the command from the attribute registers
175	 * a name that does not exist (`ripgrep`) and leaves the real binary
176	 * unregistered.
177	 * Nix-provisioned packages need no entry: the /nix/store scan in
178	 * `discoverBinaries` already finds their real binaries whatever they are named.
179	 * A package with no entry contributes nothing outside /nix/store, which fails
180	 * closed — baking a new CLI into the image is already an image change, so it
181	 * lands here in the same commit.
182	 */
183	const IMAGE_BAKED_EXECUTABLES: ReadonlyMap<string, readonly string[]> = new Map(
184	  [
185	    ["git", ["git"]],
186	    ["gh", ["gh"]],
187	    ["ripgrep", ["rg"]],
188	  ]
189	);
190	
191	/**
192	 * Discover binaries to register as custom commands:
193	 * 1. All executables from /nix/store/ PATH directories
194	 * 2. `lobu`, plus the executables of the NIX_PACKAGES entries listed in
195	 *    IMAGE_BAKED_EXECUTABLES, from anywhere on PATH — a connector-contributed
196	 *    CLI may be baked into the image rather than provisioned by nix
197	 *
198	 * UNSANDBOXED_INTERPRETERS are filtered out unless the spawned worker has
199	 * LOBU_ALLOW_UNSANDBOXED_EXEC=1 in its env (set explicitly per-agent for
200	 * cases that genuinely need a full interpreter).
201	 */
202	function discoverBinaries(): Map<string, string> {
203	  const binaries = new Map<string, string>();
204	  const pathDirs = (process.env.PATH || "").split(":");
205	  const allowUnsandboxed =
206	    process.env.LOBU_ALLOW_UNSANDBOXED_EXEC === "1" ||
207	    process.env.LOBU_ALLOW_UNSANDBOXED_EXEC === "true";
208	
209	  const isAllowed = (name: string): boolean =>
210	    allowUnsandboxed || !UNSANDBOXED_INTERPRETERS.has(name);
211	
212	  for (const dir of pathDirs) {
213	    if (!dir.includes("/nix/store/")) continue;
214	    try {
215	      for (const entry of fs.readdirSync(dir)) {
216	        if (!isAllowed(entry)) continue;
217	        const fullPath = path.join(dir, entry);
218	        try {
219	          fs.accessSync(fullPath, fs.constants.X_OK);
220	          if (!binaries.has(entry)) binaries.set(entry, fullPath);
221	        } catch {
222	          // not executable
223	        }
224	      }
225	    } catch {
226	      // directory not readable
227	    }
228	  }
229	
230	  // Discover known CLI tools, plus the commands of the declared image-baked
231	  // packages, from the FULL PATH rather than only /nix/store.

