input.old_string:
/**
 * Why a spawned binary may be registered at all.
 *
 * `sandbox`  — a real per-exec sandbox (bwrap / sandbox-exec) confines it.
 * `single-tenant` — the deployment declares it hosts one tenant, so there is
 *   no sibling workspace to read. The operator asserts this; it is never
 *   inferred, because nothing observable from inside the container
 *   distinguishes "one tenant" from "one tenant so far".
 * `unsandboxed-opt-in` — the pre-existing escape hatch for trusted agents.
 */
export interface WorkerIsolation {
  isolated: boolean;
  reason: "sandbox" | "single-tenant" | "unsandboxed-opt-in" | "none";
}

/**
 * Resolve whether this worker is isolated enough to run spawned binaries.
 *
 * Order matters only for reporting — any one source is sufficient. The default
 * is NOT isolated: a deployment that declares nothing is treated as
 * multi-tenant, so the unsafe case is the one an operator has to opt into
 * rather than the one they get by forgetting.
 */
export function resolveWorkerIsolation(): WorkerIsolation {
  if (probeSandboxStrategy().kind !== "none") {
    return { isolated: true, reason: "sandbox" };
  }
  // An operator assertion about the DEPLOYMENT ("only my own org runs here"),
  // not a feature switch. Anything other than an explicit 1/true — including
  // unset, empty, or a typo — means multi-tenant, so the safe reading is the
  // one you get by default.
  const singleTenant = process.env.LOBU_SINGLE_TENANT_HOST;
  if (singleTenant === "1" || singleTenant?.toLowerCase() === "true") {
    return { isolated: true, reason: "single-tenant" };
  }
  if (
    process.env.LOBU_ALLOW_UNSANDBOXED_EXEC === "1" ||
    process.env.LOBU_ALLOW_UNSANDBOXED_EXEC === "true"
  ) {
    return { isolated: true, reason: "unsandboxed-opt-in" };
  }
  return { isolated: false, reason: "none" };
}

