1	/**
2	 * Worker-side just-bash bootstrap for embedded deployment mode.
3	 *
4	 * Creates a just-bash Bash instance from environment variables and wraps it
5	 * as a BashOperations interface for pi-coding-agent's bash tool.
6	 *
7	 * When nix binaries are detected on PATH (via nix-shell wrapper from gateway)
8	 * or known CLI tools (e.g. lobu) are found, they are registered as
9	 * just-bash customCommands that delegate to real exec.
10	 */
11	
12	import { execFile } from "node:child_process";
13	import fs from "node:fs";
14	import path from "node:path";
15	import type { BashOperations } from "@mariozechner/pi-coding-agent";
16	import { buildAgentEnv } from "../shared/worker-env-keys";
17	import type { GatewayParams } from "@lobu/plugin-toolkit";
18	import { buildEgressFetch } from "./egress-fetch";
19	import {
20	  type SandboxStrategy,
21	  probeSandboxStrategy,
22	  wrapInvocation,
23	} from "./exec-sandbox";
24	import type { McpCliCommand, McpRuntimeRef } from "./mcp-cli-commands";
25	import { buildMcpCliCommands } from "./mcp-cli-commands";
26	import { getWorkerRuntimeProvider } from "./runtime";
27	
28	const EMBEDDED_BASH_LIMITS = {
29	  maxCommandCount: 50_000,
30	  maxLoopIterations: 50_000,
31	  maxCallDepth: 50,
32	} as const;
33	
34	interface SandboxContext {
35	  strategy: SandboxStrategy;
36	  workspaceDir: string;
37	  /** Whether the spawned binary may open sockets. just-bash's domain allowlist
38	   * still gates the interpreter; this controls the OS network namespace. */
39	  allowNet?: boolean;
40	  /** Per-invocation cwd inside bwrap's /workspace namespace. */
41	  bwrapCwd?: string;
42	}
43	
44	export function buildBinaryInvocation(
45	  binaryPath: string,
46	  args: string[],
47	  sandbox?: SandboxContext
48	): { command: string; args: string[] } {
49	  let inner: { command: string; args: string[] } = {
50	    command: binaryPath,
51	    args,
52	  };
53	  try {
54	    const firstLine =
55	      fs.readFileSync(binaryPath, "utf8").split("\n", 1)[0] || "";
56	    if (firstLine === "#!/usr/bin/env node" || firstLine.endsWith("/node")) {
57	      inner = { command: "node", args: [binaryPath, ...args] };
58	    }
59	  } catch {
60	    // Fall back to executing the binary directly.
61	  }
62	
63	  if (!sandbox) return inner;
64	  return wrapInvocation(sandbox.strategy, inner, {
65	    workspaceDir: sandbox.workspaceDir,
66	    allowNet: sandbox.allowNet ?? true,
67	    bwrapCwd: sandbox.bwrapCwd,
68	  });
69	}
70	
71	/**
72	 * Binaries that are full code-execution capabilities. If they land on the
73	 * just-bash allowlist, the depth/loop caps are moot — the agent can run
74	 * arbitrary code through them. They are excluded by default; an agent that
75	 * genuinely needs them must opt in via
76	 * `LOBU_ALLOW_UNSANDBOXED_EXEC=1` (set per-agent in lobu.config.ts).
77	 */
78	const UNSANDBOXED_INTERPRETERS = new Set<string>([
79	  "node",
80	  "nodejs",
81	  "bun",
82	  "deno",
83	  "python",
84	  "python3",
85	  "ruby",
86	  "perl",
87	  "lua",
88	  "bash",
89	  "sh",
