125	/**
126	 * Executables installed by a declared nix package, for the packages whose CLI
127	 * is baked into the runtime image (docker/app/Dockerfile) instead of being
128	 * provisioned under /nix/store.
129	 *
130	 * A package attribute does NOT name its commands (`ripgrep` installs `rg`), so
131	 * this listing is explicit. Inferring the command from the attribute registers
132	 * a name that does not exist (`ripgrep`) and leaves the real binary
133	 * unregistered.
134	 * Nix-provisioned packages need no entry: the /nix/store scan in
135	 * `discoverBinaries` already finds their real binaries whatever they are named.
136	 * A package with no entry contributes nothing outside /nix/store, which fails
137	 * closed — baking a new CLI into the image is already an image change, so it
138	 * lands here in the same commit.
139	 */
140	const IMAGE_BAKED_EXECUTABLES: ReadonlyMap<string, readonly string[]> = new Map(
141	  [
142	    ["git", ["git"]],
143	    ["gh", ["gh"]],
144	    ["ripgrep", ["rg"]],
145	  ]
146	);
147	
148	/**
149	 * Discover binaries to register as custom commands:
150	 * 1. All executables from /nix/store/ PATH directories
151	 * 2. `lobu`, plus the executables of the NIX_PACKAGES entries listed in
152	 *    IMAGE_BAKED_EXECUTABLES, from anywhere on PATH — a connector-contributed
153	 *    CLI may be baked into the image rather than provisioned by nix
154	 *
155	 * UNSANDBOXED_INTERPRETERS are filtered out unless the spawned worker has
156	 * LOBU_ALLOW_UNSANDBOXED_EXEC=1 in its env (set explicitly per-agent for
157	 * cases that genuinely need a full interpreter).
158	 */
159	function discoverBinaries(): Map<string, string> {
160	  const binaries = new Map<string, string>();
161	  const pathDirs = (process.env.PATH || "").split(":");
162	  const allowUnsandboxed =
163	    process.env.LOBU_ALLOW_UNSANDBOXED_EXEC === "1" ||
164	    process.env.LOBU_ALLOW_UNSANDBOXED_EXEC === "true";
165	
166	  const isAllowed = (name: string): boolean =>
167	    allowUnsandboxed || !UNSANDBOXED_INTERPRETERS.has(name);
168	
169	  for (const dir of pathDirs) {
170	    if (!dir.includes("/nix/store/")) continue;
171	    try {
172	      for (const entry of fs.readdirSync(dir)) {
173	        if (!isAllowed(entry)) continue;
174	        const fullPath = path.join(dir, entry);
175	        try {
176	          fs.accessSync(fullPath, fs.constants.X_OK);
177	          if (!binaries.has(entry)) binaries.set(entry, fullPath);
178	        } catch {
179	          // not executable
180	        }
181	      }
182	    } catch {
183	      // directory not readable
184	    }
185	  }
186	
187	  // Discover known CLI tools, plus the commands of the declared image-baked
188	  // packages, from the FULL PATH rather than only /nix/store.
189	  //
190	  // `NIX_PACKAGES` is the declared tooling for this deployment. A declared tool
191	  // is not necessarily provisioned by nix: the production image bakes `git` and
192	  // `gh` into /usr/bin (see docker/app/Dockerfile), which is on PATH but not
193	  // under /nix/store, so the scan above never sees it. Without this the
194	  // contributed CLI is present on the filesystem and still exits 127 through
195	  // the agent's bash — the credential works and the command does not.
196	  const contributed = (process.env.NIX_PACKAGES || "")
197	    .split(",")
198	    .map((name) => name.trim())
199	    // A nix attribute path (`pkgs.gh`, `nixpkgs#gh`) names the package; the
200	    // commands it installs are NOT derivable from that name, so they come from
201	    // the explicit listing above.
202	    .map((name) => name.split(/[.#]/).pop() ?? "")
203	    .flatMap((pkg) => IMAGE_BAKED_EXECUTABLES.get(pkg) ?? []);
204	
205	  for (const name of ["lobu", ...contributed]) {
206	    if (binaries.has(name)) continue;
207	    if (!isAllowed(name)) continue;
208	    for (const dir of pathDirs) {
209	      const fullPath = path.join(dir, name);
210	      try {
211	        fs.accessSync(fullPath, fs.constants.X_OK);
212	        binaries.set(name, fullPath);
213	        break;
214	      } catch {
215	        // not found
216	      }
217	    }
218	  }
219	
220	  return binaries;
221	}
