1	/**
2	 * The worker's own environment must not be readable from agent bash.
3	 *
4	 * Reproduced before the fix: with the two-entry denylist, `echo $ENCRYPTION_KEY`
5	 * returned the real value through the agent's shell under the STRICTEST posture
6	 * (cloud mode, no sandbox, no unsandboxed opt-in, zero spawned binaries
7	 * registered). Nothing had to escape a sandbox — `stripEnv` copied the whole
8	 * gateway env into the just-bash instance and removed only WORKER_TOKEN and
9	 * DISPATCHER_URL, so the values were simply there.
10	 */
11	import { afterEach, describe, expect, test } from "bun:test";
12	import fs from "node:fs";
13	import os from "node:os";
14	import path from "node:path";
15	import { createEmbeddedBashOps } from "../embedded/just-bash-bootstrap";
16	import { buildAgentEnv } from "../shared/worker-env-keys";
17	
18	const tempDirs: string[] = [];
19	const TOUCHED = [
20		"LOBU_EXEC_SANDBOX",
21		"LOBU_ALLOW_UNSANDBOXED_EXEC",
22		"LOBU_WORKSPACE_BACKEND",
23		"ENCRYPTION_KEY",
24		"JWT_SECRET",
25		"DATABASE_URL",
26		"ANTHROPIC_API_KEY",
27		"GH_TOKEN",
28		"LOBU_AGENT_ENV_GREETING",
29	] as const;
30	const original = Object.fromEntries(
31		TOUCHED.map((k) => [k, process.env[k]]),
32	) as Record<string, string | undefined>;
33	
34	afterEach(() => {
35		for (const dir of tempDirs.splice(0)) {
36			fs.rmSync(dir, { recursive: true, force: true });
37		}
38		for (const key of TOUCHED) {
39			const value = original[key];
40			if (value === undefined) delete process.env[key];
41			else process.env[key] = value;
42		}
43	});
44	
45	async function echoFromAgentBash(varName: string): Promise<string> {
46		const workspace = fs.realpathSync(
47			fs.mkdtempSync(path.join(os.tmpdir(), "lobu-envleak-")),
48		);
49		tempDirs.push(workspace);
50		// Strictest posture: no sandbox, no opt-in, nothing registered.
51		process.env.LOBU_EXEC_SANDBOX = "off";
52		delete process.env.LOBU_ALLOW_UNSANDBOXED_EXEC;
53		delete process.env.LOBU_WORKSPACE_BACKEND;
54	
55		const ops = await createEmbeddedBashOps({ workspaceDir: workspace });
56		const chunks: string[] = [];
57		await ops.exec(`echo $${varName}`, "/", {
58			onData: (chunk) => chunks.push(chunk.toString()),
59			timeout: 5,
60		});
61		return chunks.join("").trim();
62	}
63	
64	describe("gateway secrets are not readable from agent bash", () => {
65		test("REGRESSION: ENCRYPTION_KEY does not reach the agent's shell", async () => {
66			process.env.ENCRYPTION_KEY = "vault-key-must-not-leak";
67			expect(await echoFromAgentBash("ENCRYPTION_KEY")).toBe("");
68		});
69	
70		test("REGRESSION: neither do the other gateway secrets", async () => {
71			process.env.JWT_SECRET = "jwt-must-not-leak";
72			process.env.DATABASE_URL = "postgres://must-not-leak";
73			process.env.ANTHROPIC_API_KEY = "sk-must-not-leak";
74			expect(await echoFromAgentBash("JWT_SECRET")).toBe("");
75			expect(await echoFromAgentBash("DATABASE_URL")).toBe("");
76			expect(await echoFromAgentBash("ANTHROPIC_API_KEY")).toBe("");
77		});
78	
79		test("PATH still reaches the shell, or nothing resolves", async () => {
80			expect(await echoFromAgentBash("PATH")).not.toBe("");
81		});
82	
83		test("an explicitly-intended LOBU_AGENT_ENV_ value does reach it", async () => {
84			process.env.LOBU_AGENT_ENV_GREETING = "hello-agent";
85			expect(await echoFromAgentBash("LOBU_AGENT_ENV_GREETING")).toBe(
86				"hello-agent",
87			);
88		});
89	
90		test("the connector-contributed GH_TOKEN lease reaches agent tooling", async () => {
91			process.env.GH_TOKEN = "ghs_short_lived_lease";
92			expect(await echoFromAgentBash("GH_TOKEN")).toBe("ghs_short_lived_lease");
93		});
94	});
95	
96	describe("buildAgentEnv", () => {
97		test("keeps allowlisted names and drops everything else", () => {
98			const out = buildAgentEnv({
99				PATH: "/usr/bin",
100				HOME: "/home/agent",
101				GH_TOKEN: "ghs_short_lived_lease",
102				ENCRYPTION_KEY: "nope",
103				SOME_FUTURE_SECRET: "also nope",
104			});
105			expect(out.PATH).toBe("/usr/bin");
106			expect(out.HOME).toBe("/home/agent");
107			expect(out.GH_TOKEN).toBe("ghs_short_lived_lease");
108			expect(out).not.toHaveProperty("ENCRYPTION_KEY");
109			// The property that a denylist cannot have: a secret nobody has heard of
110			// yet is excluded by default rather than included by default.
111			expect(out).not.toHaveProperty("SOME_FUTURE_SECRET");
112		});
113	
114		test("drops the previously-denylisted keys too", () => {
115			const out = buildAgentEnv({
116				WORKER_TOKEN: "signed-token",
117				DISPATCHER_URL: "https://dispatcher",
118			});
119			expect(out).not.toHaveProperty("WORKER_TOKEN");
120			expect(out).not.toHaveProperty("DISPATCHER_URL");
121		});
122	
123		test("`extra` passes through unfiltered — it is what the call site intends", () => {
124			const out = buildAgentEnv(
125				{ ENCRYPTION_KEY: "nope" },
126				{ XDG_CONFIG_HOME: "/runtime/.config" },
127			);
128			expect(out.XDG_CONFIG_HOME).toBe("/runtime/.config");
129			expect(out).not.toHaveProperty("ENCRYPTION_KEY");
130		});
131	
132		test("undefined values never materialise as empty strings", () => {
133			const out = buildAgentEnv(
134				{ PATH: undefined },
135				{ XDG_CONFIG_HOME: undefined },
136			);
137			expect(out).not.toHaveProperty("PATH");
138			expect(out).not.toHaveProperty("XDG_CONFIG_HOME");
139		});
140	});

