/**
 * Live e2e probe: run the REAL spawn paths inside a process whose environment
 * is loaded with gateway secrets, exactly as a deployed worker pod's would be.
 *
 * This is not a unit test. Nothing is mocked. We set the secrets on the actual
 * process.env of this process, then invoke each production spawn path and read
 * back what the child process could see.
 */
import { createEmbeddedBashOps } from "../../../../../../Users/burakemre/Code/lobu/.claude/worktrees/worker-env-allowlist/packages/agent-worker/src/embedded/just-bash-bootstrap";

const SECRETS: Record<string, string> = {
  ENCRYPTION_KEY: "LEAK_encryption_key_aaaa",
  JWT_SECRET: "LEAK_jwt_secret_bbbb",
  DATABASE_URL: "postgres://LEAK_db_cccc@host/db",
  ANTHROPIC_API_KEY: "sk-LEAK_anthropic_dddd",
  WORKER_TOKEN: "LEAK_worker_token_eeee",
  DISPATCHER_URL: "https://LEAK_dispatcher_ffff",
  OPENAI_API_KEY: "sk-LEAK_openai_gggg",
  SLACK_CLIENT_SECRET: "LEAK_slack_hhhh",
  GOOGLE_CLIENT_SECRET: "LEAK_google_iiii",
  STRIPE_SECRET_KEY: "LEAK_stripe_jjjj",
  AWS_SECRET_ACCESS_KEY: "LEAK_aws_kkkk",
  SOME_BRAND_NEW_SECRET_2027: "LEAK_future_llll",
};

for (const [k, v] of Object.entries(SECRETS)) process.env[k] = v;

// Things that SHOULD reach the agent.
process.env.GH_TOKEN = "ghs_lease_should_pass";
process.env.LOBU_AGENT_ENV_GREETING = "hello_should_pass";

process.env.LOBU_EXEC_SANDBOX = "off";
delete process.env.LOBU_ALLOW_UNSANDBOXED_EXEC;
delete process.env.LOBU_WORKSPACE_BACKEND;

const fs = await import("node:fs");
const os = await import("node:os");
const path = await import("node:path");

const workspace = fs.realpathSync(
  fs.mkdtempSync(path.join(os.tmpdir(), "lobu-e2e-probe-"))
);

const ops = await createEmbeddedBashOps({ workspaceDir: workspace });

async function run(cmd: string): Promise<string> {
  const chunks: string[] = [];
  await ops.exec(cmd, "/", {
    onData: (c: Buffer | string) => chunks.push(c.toString()),
    timeout: 15,
  });
  return chunks.join("");
}

console.log("=== PROBE 1: dump the entire agent-visible environment ===");
const dump = await run("env");
console.log(dump || "(env produced no output)");

console.log("\n=== PROBE 2: grep the agent's env for the LEAK marker ===");
const leakGrep = await run("env | grep LEAK || echo NO_LEAK_FOUND");
console.log(leakGrep);

console.log("\n=== PROBE 3: echo each secret by name ===");
for (const key of Object.keys(SECRETS)) {
