/**
 * Full-chain e2e, in the attacker's order of operations:
 *   1. agent reads HTTP_PROXY out of its own environment (allowlisted, so it CAN)
 *   2. agent parses the Basic-auth password out of that URL
 *   3. agent tries to use that credential against the WORKER surface
 *
 * Before the split, step 3 succeeded and the agent had the worker's identity.
 */
process.env.ENCRYPTION_KEY ||= "0".repeat(64);

import {
  generateWorkerTokenPair,
  verifyWorkerToken,
  verifyEgressProxyToken,
} from "./packages/core/src/worker/auth";
import { buildAgentEnv } from "./packages/agent-worker/src/shared/worker-env-keys";

const { workerToken, egressProxyToken } = generateWorkerTokenPair(
  "user-1",
  "conv-1",
  "dep-1",
  { organizationId: "org-1", channelId: "chan-1", expiresInSeconds: 3600 }
);

// Exactly what deployment-manager.buildProxyUrl produces.
const proxyUrl = `REDACTED`;

// The pod environment as the gateway assembles it.
const podEnv: Record<string, string> = {
  PATH: "/usr/bin:/bin",
  HOME: "/home/agent",
  HTTP_PROXY: proxyUrl,
  HTTPS_PROXY: proxyUrl,
  WORKER_TOKEN: workerToken,
  DISPATCHER_URL: "https://gateway.internal",
  ENCRYPTION_KEY: "vault-key",
};

const agentEnv = buildAgentEnv(podEnv);

console.log("=== step 1: what can the agent see? ===");
console.log("WORKER_TOKEN visible :", agentEnv.WORKER_TOKEN ? "YES (BUG)" : "no");
console.log("ENCRYPTION_KEY visible:", agentEnv.ENCRYPTION_KEY ? "YES (BUG)" : "no");
console.log("HTTP_PROXY visible   :", agentEnv.HTTP_PROXY ? "yes (by design — needed for egress)" : "no");

console.log("\n=== step 2: harvest the credential out of HTTP_PROXY ===");
const harvested = new URL(agentEnv.HTTP_PROXY!).password;
console.log("harvested credential length:", harvested.length);
console.log("harvested === workerToken   :", harvested === workerToken ? "YES (VULNERABLE)" : "no — it is a different credential");

console.log("\n=== step 3: try the harvested credential on each surface ===");
