const { workerToken, egressProxyToken } = generateWorkerTokenPair("u","c","dep-1",{organizationId:"o",channelId:"ch",expiresInSeconds:3600});

// Exactly what an HTTP client does with http://dep-1:<tok>@host:8118
function toHeader(user: string, pass: string) {
  return "Basic " + Buffer.from(`${user}:${pass}`).toString("base64");
}
// Exactly what extractProxyCredentials does (http-proxy.ts:409-416)
function parse(h: string) {
  const m = h.match(/^Basic\s+(.+)$/i)!;
  const d = Buffer.from(m[1], "base64").toString("utf-8");
  const i = d.indexOf(":");
  return { deploymentName: d.substring(0,i), token: d.substring(i+1) };
}

for (const [label, tok] of [["egressProxyToken", egressProxyToken], ["workerToken (attacker replay)", workerToken]] as const) {
  const parsed = parse(toHeader("dep-1", tok));
  const exact = parsed.token === tok;
  const egress = !!verifyEgressProxyToken(parsed.token);
  const worker = !!verifyWorkerToken(parsed.token);
  console.log(`${label}:`);
  console.log(`  survives header roundtrip : ${exact}`);
  console.log(`  deploymentName parsed     : ${parsed.deploymentName}`);
  console.log(`  accepted @ EGRESS surface : ${egress}`);
  console.log(`  accepted @ WORKER surface : ${worker}`);
}
EOF
