/**
 * Why a lease could not be minted. Returned INSTEAD of a token so the caller can
 * tell the agent what is unavailable — a silently absent credential is the worse
 * failure, because the agent improvises around it rather than reporting it.
 */
export interface CredentialLeaseFailure {
  reason: string;
}

/** Either a usable lease or the reason there is none. Never both. */
export type CredentialLeaseResult = CredentialLease | CredentialLeaseFailure;

export function isLeaseFailure(
  result: CredentialLeaseResult | null
): result is CredentialLeaseFailure {
  return result !== null && "reason" in result;
}

