1	/**
2	 * Short-lived credential leases for connector-contributed agent tooling.
3	 *
4	 * A LEASE is a short-lived, provider-derived credential minted per deployment
5	 * and injected into the agent sandbox as a real env var. This does not weaken
6	 * the workers-never-receive-durable-credentials invariant: what the worker
7	 * holds expires on its own (GitHub installation tokens last ~1h) and can be
8	 * revoked at the provider without touching the stored connection credential,
9	 * which never leaves the gateway.
10	 *
11	 * Providers with no derived-token support contribute no credential. The worker
12	 * egress proxy raw-tunnels HTTPS CONNECT traffic, so it cannot replace an
13	 * opaque placeholder inside a CLI's TLS request.
14	 *
15	 * Multi-replica: minting is STATELESS per deployment. No lease is persisted and
16	 * no replica reads another's lease; two pods minting for the same connection
17	 * simply hold two independently valid tokens. Expiry is the provider's, so a
18	 * deployment outliving its lease re-mints on restart; mid-run refresh is
19	 * deliberately out of scope for v1.
20	 */
21	
22	import { createLogger } from "@lobu/core";
23	import { getInstallationTokenRegistry } from "../installation/registry.js";
24	import {
25	  InstallationTokenError,
26	  type MintedInstallationToken,
27	} from "../installation/installation-token-provider.js";
28	import type { AppInstallationStore } from "../../lobu/stores/app-installation-store.js";
29	
30	const logger = createLogger("credential-lease");
31	
32	/** The connection a lease is being minted for, as resolved from the database. */
33	export interface LeaseSubject {
34	  /** `connections.id`. */
35	  connectionId: number;
36	  organizationId: string;
37	  connectorKey: string;
38	  /**
39	   * `app_installations.id` this connection is bound to (`config.installation_ref`),
40	   * or null when the connection has no App-installation backing.
41	   */
42	  installationRef: number | null;
43	  /** The connector's `app_installation` auth method provider, e.g. `'github'`. */
44	  provider: string | null;
45	  /** Method-declared provider instance; defaults to `'cloud'` when unset. */
46	  providerInstance: string | null;
47	  /** Gateway env var NAMES for the App id / private key (never their values). */
48	  appIdKey: string | null;
49	  privateKeyKey: string | null;
50	}
51	
52	/** Who the lease is minted for — stamped into the audit line. */
53	export interface LeaseScopeHints {
54	  agentId: string;
55	  deploymentName: string;
56	  /** The run this deployment is serving, when the caller knows it. */
57	  runId?: number;
58	}
59	
60	/** A minted lease value injected into the sandbox. */
61	export interface CredentialLease {
62	  token: string;
63	}
64	
65	/**
66	 * Why a lease could not be minted. Returned INSTEAD of a token so the caller can
67	 * tell the agent what is unavailable — a silently absent credential is the worse
68	 * failure, because the agent improvises around it rather than reporting it.
69	 */
70	export interface CredentialLeaseFailure {
71	  reason: string;
72	}
73	
74	/** Either a usable lease or the reason there is none. Never both. */
75	export type CredentialLeaseResult = CredentialLease | CredentialLeaseFailure;
76	
77	export function isLeaseFailure(
78	  result: CredentialLeaseResult | null
79	): result is CredentialLeaseFailure {
80	  return result !== null && "reason" in result;
81	}
82	
83	/**
84	 * Per-provider lease minting. One implementation per credential-derivation
85	 * scheme; `provider` matches the connector's `app_installation` method provider.
86	 */
87	export interface CredentialLeaseProvider {
88	  readonly provider: string;
89	  /**
90	   * Mint a short-lived credential for `subject`, a {@link CredentialLeaseFailure}
91	   * carrying why it could not (inactive install, provider exchange failure), or
92	   * null when this connection has no installation backing at all.
93	   *
94	   * Never throws for an unmintable connection — a broken GitHub install must not
95	   * fail the whole deployment. But a failure is REPORTED rather than swallowed:
96	   * the resolver surfaces it so the agent is told the CLI is unauthenticated
97	   * instead of discovering it by running a command and improvising.
98	   */
99	  mint(
100	    subject: LeaseSubject,
101	    scope: LeaseScopeHints
102	  ): Promise<CredentialLeaseResult | null>;
103	}
104	
105	/**
106	 * GitHub App installation-token lease.
107	 *
108	 * Delegates to the existing per-pod {@link getInstallationTokenRegistry} — the
109	 * same minting path the connector credential resolver uses — so the App private
110	 * key, the signed App JWT, and the `/access_tokens` exchange all stay
111	 * gateway-side and there is exactly one implementation of the exchange.
112	 *
113	 * Scope: GitHub's installation token carries the installation's own
114	 * repository/permission selection, chosen by the org admin during install. We
115	 * deliberately do NOT narrow further per agent here — the token API's
116	 * `repositories`/`permissions` narrowing needs a repo allow-list this feature
117	 * has no UI for yet, and silently minting a narrower token than the operator
118	 * granted would make `gh` fail in ways the agent cannot explain. Narrowing is
119	 * the follow-up that pairs with a per-agent connector-write Access matrix.
120	 */
121	export class GitHubCredentialLeaseProvider implements CredentialLeaseProvider {
122	  readonly provider = "github";
123	
124	  constructor(private readonly installStore: AppInstallationStore) {}
125	
126	  async mint(
127	    subject: LeaseSubject,
128	    scope: LeaseScopeHints
129	  ): Promise<CredentialLease | null> {
130	    if (subject.installationRef == null) {
131	      // Connector supports App installs but this connection isn't bound to one
132	      // (OAuth/PAT fallback). There is no derivable short-lived credential, and
133	      // handing over the stored token would breach the worker-creds invariant.
134	      logger.debug(
135	        {
136	          connection_id: subject.connectionId,
137	          agent_id: scope.agentId,
138	        },
139	        "No installation backing for connection — no lease minted"
140	      );
141	      return null;
142	    }
143	
144	    const install = await this.installStore.getById(subject.installationRef);
145	    if (!install) {
146	      logger.warn(
147	        {
148	          connection_id: subject.connectionId,
149	          install_id: subject.installationRef,
150	        },
151	        "Agent-tooling lease: connection references a missing install row"
152	      );
153	      return { reason: "install_missing" };
154	    }
155	
156	    // Tenancy guard, mirroring the connector credential resolver: a connection
157	    // whose `installation_ref` points at ANOTHER org's install must never yield
158	    // that org's token. Reject before minting, never after.
159	    if (install.organizationId !== subject.organizationId) {
160	      logger.warn(
