93	  "WORKER_TOKEN",
94	  "DISPATCHER_URL",
95	  "WORKSPACE_DIR",
96	  "PATH",
97	  "HOME",
98	  "NODE_ENV",
99	  "NODE_OPTIONS",
100	  "BUN_OPTIONS",
101	  "LD_PRELOAD",
102	  "LD_LIBRARY_PATH",
103	  "HTTP_PROXY",
104	  "HTTPS_PROXY",
105	  "NO_PROXY",
106	  "ALL_PROXY",
107	]);
