190	    : [];
191	
192	  if (packages.length === 0 && env.length === 0 && domains.length === 0) {
193	    return null;
194	  }
195	  return {
196	    ...(packages.length > 0 ? { nix: { packages } } : {}),
197	    ...(env.length > 0 ? { env } : {}),
198	    ...(domains.length > 0 ? { domains } : {}),
199	  };
200	}
