  async exec(ctx: RuntimeExecContext): Promise<RuntimeExecResult> {
    const sandboxName = stableSandboxName({
      organizationId: ctx.organizationId,
      agentId: ctx.agentId,
      conversationId: ctx.conversationId,
    });
    const networkPolicy = networkPolicyFromDomains(
      ctx.allowedDomains,
      ctx.deniedDomains
    );
    const sandbox = await getSandbox({
      name: sandboxName,
      networkPolicy,
      credentials: ctx.credentials.values,
    });

    await sandbox.fs.mkdir(REMOTE_WORKSPACE_DIR, { recursive: true });

    const result = await sandbox.runCommand({
      cmd: "/bin/bash",
      args: ["-lc", ctx.command],
      cwd: remoteCwd(ctx.cwd, ctx.workspaceDir, REMOTE_WORKSPACE_DIR),
      env: ctx.env,
      timeoutMs: ctx.timeoutMs,
    });
    const [stdout, stderr] = await Promise.all([
      result.stdout(),
      result.stderr(),
    ]);

    return {
      stdout,
      stderr,
      exitCode: result.exitCode,
      meta: {
        name: sandbox.name,
        persistent: sandbox.persistent,
        cwd: sandbox.cwd,
      },
    };
  },
};

