function direct(command: string): { out: string; code: number } {
  try {
    const out = execFileSync("/bin/bash", ["-lc", command], {
      encoding: "utf8",
      stdio: ["ignore", "pipe", "pipe"],
    });
    return { out: out.trim(), code: 0 };
