async function fetchAgentThreads(
	agentId: string,
	orgSlug: string | null | undefined,
	options?: { strict?: boolean; scope?: "all" },
): Promise<AgentThreadItem[]> {
	const path = options?.scope === "all" ? "/threads?scope=all" : "/threads";
	const res = await fetchWithTimeout(agentHistoryUrl(agentId, path), {
		credentials: "include",
		headers: orgScopedHeaders(orgSlug),
	});
	if (res.status === 401 || res.status === 403) return [];
	if (!res.ok) {
		if (options?.strict) {
			await throwIfNotOk(res, "Failed to fetch agent threads");
		}
		return [];
	}
	const data = (await res.json()) as { threads?: AgentThreadItem[] };
	return Array.isArray(data.threads) ? data.threads : [];
}

export function agentThreadsQueryOptions(
	orgSlug: string | null | undefined,
	agentId: string,
	options?: { strict?: boolean; scope?: "all" },
) {
	return {
		queryKey: [
			"agent-threads",
			orgSlug,
			agentId,
			options?.scope ?? "user",
		] as const,
		queryFn: () => fetchAgentThreads(agentId, orgSlug, options),
		staleTime: 15_000,
	};
}

