 */
export function useRecentRuns(
  ownerSlug: string | null,
  opts?: { limit?: number; runTypes?: string[] }
) {
  const limit = opts?.limit ?? 12;
  const runTypes = opts?.runTypes;
  return useQuery({
    queryKey: ['recent-runs', ownerSlug ?? null, limit, runTypes ?? null],
    queryFn: async () => {
      const res = await apiCall<ListRunsResult>(
