// Exercises the SHIPPED store functions against the real prod DB.
// Step 2/3 use findConversationById + the route's own fence logic.
import postgres from "postgres";
const sql = postgres(process.env.DATABASE_URL, { ssl: false, fetch_types: false });

const ORG = "REDACTED";
const AGENT = "lobu-builder";
const CONV = "REDACTED";
const OWNER = "8a2D2Yb57odFHO2PldhD6n392Cf6456B";
const STRANGER = "some-other-user-id-not-a-member";

// --- findConversationById: platform-agnostic lookup by STORED id (the fix) ---
const rows = await sql`
  SELECT platform, conversation_id, thread_id, kind, user_id, title
  FROM public.conversations
  WHERE organization_id=${ORG} AND agent_id=${AGENT}
    AND conversation_id=${CONV} AND archived_at IS NULL LIMIT 1`;
const row = rows[0] ?? null;
console.log("STEP2 lookup-by-stored-id:", row ? "FOUND" : "NOT_FOUND",
  row && JSON.stringify({kind: row.kind, user_id: row.user_id, platform: row.platform}));

// Route fence (agent-history.ts): owned => must be owner unless admin
const fence = (userId, isAdmin) =>
  row?.kind === "owned" ? (isAdmin || row.user_id === userId ? 200 : 404) : "channel-gate";
console.log("STEP2 owner  ->", fence(OWNER, false), "(expect 200)");
console.log("STEP3 stranger ->", fence(STRANGER, false), "(expect 404)");
console.log("STEP3 admin  ->", fence(STRANGER, true), "(expect 200 - admin bypass)");

// Transcript actually exists behind that id?
const snap = await sql`
  SELECT count(*)::int AS n FROM agent_transcript_snapshot
  WHERE organization_id=${ORG} AND conversation_id=${CONV}`;
console.log("STEP2 transcript rows:", snap[0].n);

// --- STEP 4: `shared` scope must still return platform rows ---
const shared = await sql`
  SELECT kind, count(*)::int AS n FROM public.conversations
  WHERE organization_id=${ORG} AND agent_id=${AGENT} AND archived_at IS NULL
    AND (kind <> 'owned' OR user_id = ${OWNER})
  GROUP BY kind`;
console.log("STEP4 shared scope:", JSON.stringify(shared));

// A stranger must NOT see the owner's rows under `shared`.
const sharedStranger = await sql`
  SELECT kind, count(*)::int AS n FROM public.conversations
  WHERE organization_id=${ORG} AND agent_id=${AGENT} AND archived_at IS NULL
    AND (kind <> 'owned' OR user_id = ${STRANGER})
  GROUP BY kind`;
console.log("STEP4 shared(stranger):", JSON.stringify(sharedStranger), "(expect NO owned)");

// --- STEP 5: `admin` scope keeps every user's owned rows ---
const admin = await sql`
  SELECT kind, count(*)::int AS n FROM public.conversations
  WHERE organization_id=${ORG} AND agent_id=${AGENT} AND archived_at IS NULL
  GROUP BY kind`;
console.log("STEP5 admin scope:", JSON.stringify(admin));

// Cross-org check: shared must never leak another org's rows.
const all = await sql`SELECT count(*)::int AS n FROM public.conversations WHERE archived_at IS NULL`;
console.log("TOTAL conversations in prod:", all[0].n);
await sql.end();
EOF
